"use strict";(self.webpackJsonp_b7707b0609808c599fc778f71703da02=self.webpackJsonp_b7707b0609808c599fc778f71703da02||[]).push([[985],{1657:(e,t,n)=>{n.r(t),n.d(t,{ACCESS_COLLECTOR_FILE_NAME:()=>i,ACCESS_COLLECTOR_SCRIPT:()=>r,ACCESS_COLLECTOR_VERSION:()=>a,ACCESS_REGISTER_FILE_NAME:()=>o,ACCESS_REGISTER_SCRIPT:()=>s});var a="1.0.0",i="Invoke-EP365AtlasAccessCollector.ps1",r="<#\r\n.SYNOPSIS\r\nEP365 Atlas access collector - scheduled read of SharePoint Online permissions for EP365 Atlas.\r\n\r\n.DESCRIPTION\r\nReads, as an Entra application signed in with a certificate (app-only), the raw permission data\r\nof the places chosen in Atlas (Access > Snapshots and differences > Scheduled collection) and,\r\noptionally, which applications have Sites.Selected grants on which sites. Writes a ZIP\r\n(manifest.json + one JSON file per module + collector.log). Atlas builds the permission snapshots\r\nfrom it with the same code it uses in the browser.\r\n\r\nThe collector ONLY READS SharePoint and Microsoft Graph. The one write is the upload of the ZIP\r\ninto the folder Inbox/<tenant id> of the Atlas library EP365AtlasAccessCollect.\r\n\r\nThe places, the tenant and the modules are written into this copy of the script when it is\r\ndownloaded from Atlas. To change the places, download the script again and run -Install again.\r\n\r\nModules:\r\n  access          role assignments of every chosen place and of every place below it with its\r\n                  own permissions (webs, lists, folders, files, items), members of SharePoint\r\n                  groups, people in Entra ID groups (transitive), site collection administrators.\r\n  sitesSelected   all sites of the tenant (OneDrive excluded) and the applications that have a\r\n                  Sites.Selected grant on each of them (Microsoft Graph /sites/{id}/permissions),\r\n                  optionally also on lists.\r\n\r\nSetup (once):\r\n  1. -NewCertificate   on the computer that runs the collector: certificate in LocalMachine\\My,\r\n                       non-exportable key; only the public part (.cer) leaves the computer\r\n  2. Register-EP365AtlasAccessCollectApp.ps1   tenant administrator, once (separate script)\r\n  3. -Install          on the computer: configuration, key access, one daily scheduled task\r\n-Upload is what the scheduled task runs. -TestConnection checks the sign-in and every permission.\r\n-Uninstall removes the task, the configuration, the local queue and the certificate.\r\nOutgoing HTTPS only to login.microsoftonline.com, graph.microsoft.com and <tenant>.sharepoint.com.\r\n\r\nApplication permissions (granted by the registration script, admin consent):\r\n  SharePoint      Sites.FullControl.All   reading role assignments needs full control in SharePoint\r\n  Microsoft Graph Sites.FullControl.All   reading Sites.Selected grants (/sites/{id}/permissions)\r\n                                          and uploading the ZIP into the Inbox folder\r\n  Microsoft Graph GroupMember.Read.All    people in Entra ID groups\r\n\r\n.PARAMETER OutputPath\r\nExport: absolute path of the folder where the ZIP is written (created when missing). Needs the\r\nconfiguration of -Install (sign-in); nothing is uploaded.\r\n\r\n.PARAMETER Modules\r\nModules to run (default: the modules chosen in Atlas).\r\n\r\n.PARAMETER ModuleTimeoutMinutes\r\nTime budget of every module (default 120 minutes). A module that runs out is reported as partial.\r\n\r\n.PARAMETER NewCertificate\r\nStep 1: creates the sign-in certificate (RSA 2048, non-exportable private key, valid 2 years) in\r\nLocalMachine\\My and exports its public part (.cer). Reuses a valid certificate created earlier.\r\n\r\n.PARAMETER Install\r\nStep 3: writes the configuration, grants the task account read access to the private key and\r\nregisters the scheduled task. Needs -TenantId, -ClientId, -DriveId, -InboxItemId (printed by\r\nRegister-EP365AtlasAccessCollectApp.ps1) and -TaskAccount (or -NoTasks).\r\n\r\n.PARAMETER TaskAccount\r\nAccount of the scheduled task, DOMAIN\\name. A group managed service account (name ending with $)\r\nneeds no password; for any other account Windows asks for the password in a hidden prompt and Task\r\nScheduler stores it (the collector never does).\r\n\r\n.PARAMETER NoTasks\r\nWith -Install: configuration and key access for the CURRENT user, no scheduled task (manual\r\nExport runs only; -DriveId and -InboxItemId may then be left out).\r\n\r\n.PARAMETER DailyAt\r\nTime of the daily run (HH:mm, default 04:30).\r\n\r\n.PARAMETER Upload\r\nRun of the scheduled task: collects, puts the ZIP into the local queue and uploads the queue.\r\n\r\n.PARAMETER TestConnection\r\nSigns in and checks SharePoint, Microsoft Graph (sites, groups) and the Inbox folder. Changes nothing.\r\n\r\n.PARAMETER Uninstall\r\nRemoves the scheduled task, the collector folder (configuration, queue, logs) and, unless\r\n-KeepCertificate, the certificate with its key. The Entra application is removed by the tenant\r\nadministrator.\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasAccessCollector.ps1 -NewCertificate\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasAccessCollector.ps1 -Install -TenantId <guid> -ClientId <guid> -DriveId <id> -InboxItemId <id> -TaskAccount FIRMA\\svc_atlas$\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasAccessCollector.ps1 -OutputPath D:\\EP365AtlasAccess\r\n\r\n.NOTES\r\nEP365 Atlas access collector. Snapshot contract: kind ep365.atlas.access-snapshot, schema version 1.\r\n#>\r\n#Requires -Version 5.1\r\n[CmdletBinding(DefaultParameterSetName = 'Export')]\r\nparam(\r\n    [Parameter(ParameterSetName = 'Export', Mandatory = $true)]\r\n    [string]$OutputPath,\r\n\r\n    [ValidateSet('access', 'sitesSelected')]\r\n    [string[]]$Modules,\r\n\r\n    [ValidateRange(1, 1440)]\r\n    [int]$ModuleTimeoutMinutes = 120,\r\n\r\n    [Parameter(ParameterSetName = 'NewCertificate', Mandatory = $true)]\r\n    [switch]$NewCertificate,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [switch]$Install,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$TenantId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$ClientId,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$DriveId,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$InboxItemId,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$TaskAccount,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [switch]$NoTasks,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$CertificateThumbprint,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$DailyAt = '04:30',\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$Proxy,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [switch]$StartNow,\r\n\r\n    [Parameter(ParameterSetName = 'Upload', Mandatory = $true)]\r\n    [switch]$Upload,\r\n\r\n    [Parameter(ParameterSetName = 'TestConnection', Mandatory = $true)]\r\n    [switch]$TestConnection,\r\n\r\n    [Parameter(ParameterSetName = 'Uninstall', Mandatory = $true)]\r\n    [switch]$Uninstall,\r\n\r\n    [Parameter(ParameterSetName = 'Uninstall')]\r\n    [switch]$KeepCertificate\r\n)\r\n\r\nSet-StrictMode -Off\r\n\r\n# ==== Built by collector/build.js from collector/access/src/*.ps1 and shared collector/src files - edit the sources, not this file ====\r\n\r\n# ===================== 10-Core: shared state, logging, value helpers, module runner =====================\r\n\r\n$script:EP365CollectorVersion = '1.2.0'\r\n$script:EP365SchemaVersion = 1\r\n$script:EP365SnapshotKind = 'ep365.atlas.farm-snapshot'\r\n$script:EP365FarmModules = @('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events', 'deep')\r\n$script:EP365Utf8NoBom = New-Object System.Text.UTF8Encoding $false\r\n$script:EP365Invariant = [System.Globalization.CultureInfo]::InvariantCulture\r\n$script:EP365State = $null\r\n$script:EP365Quiet = $false\r\n# Path of this script (copied by -Install next to the configuration; the tasks run that copy).\r\n$script:EP365ScriptPath = $PSCommandPath\r\n# Log of the scheduled runs (automatic mode): one file per day in the collector folder\\logs.\r\n$script:EP365TaskLogPath = $null\r\n\r\nfunction Write-CollectorLog {\r\n    param(\r\n        [ValidateSet('INFO', 'WARN', 'ERROR')][string]$Level = 'INFO',\r\n        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message\r\n    )\r\n    $line = '{0} [{1}] {2}' -f [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant), $Level, $Message\r\n    if (-not $script:EP365Quiet) {\r\n        if ($Level -eq 'ERROR') { Write-Host $line -ForegroundColor Red }\r\n        elseif ($Level -eq 'WARN') { Write-Host $line -ForegroundColor Yellow }\r\n        else { Write-Host $line }\r\n    }\r\n    $st = $script:EP365State\r\n    if ($null -ne $st -and $st.LogPath) {\r\n        try { [System.IO.File]::AppendAllText($st.LogPath, $line + \"`r`n\", $script:EP365Utf8NoBom) } catch { }\r\n    }\r\n    if ($script:EP365TaskLogPath) {\r\n        try { [System.IO.File]::AppendAllText($script:EP365TaskLogPath, $line + \"`r`n\", $script:EP365Utf8NoBom) } catch { }\r\n    }\r\n}\r\n\r\nfunction Format-ErrorText {\r\n    # One line, no more than 500 characters. Accepts an ErrorRecord, an Exception or a string.\r\n    param($ErrorObject)\r\n    if ($null -eq $ErrorObject) { return 'Unknown error' }\r\n    $text = $null\r\n    if ($ErrorObject -is [System.Management.Automation.ErrorRecord]) {\r\n        $ex = $ErrorObject.Exception\r\n        while ($null -ne $ex -and $ex.InnerException -and ($ex -is [System.Management.Automation.MethodInvocationException] -or $ex -is [System.Management.Automation.GetValueInvocationException] -or $ex -is [System.Reflection.TargetInvocationException])) { $ex = $ex.InnerException }\r\n        if ($null -ne $ex) { $text = $ex.Message } else { $text = [string]$ErrorObject }\r\n    } elseif ($ErrorObject -is [System.Exception]) {\r\n        $text = $ErrorObject.Message\r\n    } else {\r\n        $text = [string]$ErrorObject\r\n    }\r\n    if ([string]::IsNullOrWhiteSpace($text)) { $text = 'Unknown error' }\r\n    $text = ($text -replace '[\\r\\n\\t]+', ' ').Trim()\r\n    if ($text.Length -gt 500) { $text = $text.Substring(0, 497) + '...' }\r\n    return $text\r\n}\r\n\r\n# ---------- value helpers (unknown = $null, never 0 or '') ----------\r\n\r\nfunction Get-Prop {\r\n    # Safe property getter. Path may be dotted ('RootWeb.Title'). Returns $null when the object is\r\n    # $null, the property does not exist or its getter throws. Collections are returned as ONE object\r\n    # (use Get-PropList to enumerate).\r\n    param($Object, [Parameter(Mandatory = $true)][string]$Path)\r\n    $cur = $Object\r\n    foreach ($part in $Path.Split('.')) {\r\n        if ($null -eq $cur) { return $null }\r\n        try {\r\n            if ($cur -is [System.Collections.IDictionary]) {\r\n                if ($cur.Contains($part)) { $cur = $cur[$part] } else { return $null }\r\n            } else {\r\n                $p = $cur.PSObject.Properties[$part]\r\n                if ($null -eq $p) { return $null }\r\n                $cur = $p.Value\r\n            }\r\n        } catch {\r\n            return $null\r\n        }\r\n    }\r\n    return , $cur\r\n}\r\n\r\nfunction Get-PropList {\r\n    # Enumerates a collection property into the pipeline. Call as @(Get-PropList $o 'Name').\r\n    # A missing property or a property whose getter throws yields nothing.\r\n    param($Object, [Parameter(Mandatory = $true)][string]$Path)\r\n    $v = Get-Prop -Object $Object -Path $Path\r\n    if ($null -eq $v) { return }\r\n    if ($v -is [string]) { $v; return }\r\n    if ($v -is [System.Collections.IDictionary]) { $v; return }\r\n    if ($v -is [System.Collections.IEnumerable]) {\r\n        try { foreach ($i in $v) { $i } } catch { }\r\n        return\r\n    }\r\n    $v\r\n}\r\n\r\nfunction ConvertTo-NullableString {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    $s = [string]$Value\r\n    if ($s.Length -eq 0) { return $null }\r\n    return $s\r\n}\r\n\r\nfunction ConvertTo-NullableLong {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [string] -and [string]::IsNullOrWhiteSpace($Value)) { return $null }\r\n    try {\r\n        if ($Value -is [long] -or $Value -is [int] -or $Value -is [uint32] -or $Value -is [uint64] -or $Value -is [int16] -or $Value -is [uint16] -or $Value -is [byte] -or $Value -is [decimal]) {\r\n            return [long]$Value\r\n        }\r\n        $d = [double]$Value\r\n        if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }\r\n        return [long][math]::Round($d)\r\n    } catch { return $null }\r\n}\r\n\r\nfunction ConvertTo-NullableInt {\r\n    param($Value)\r\n    $l = ConvertTo-NullableLong $Value\r\n    if ($null -eq $l) { return $null }\r\n    if ($l -gt [int]::MaxValue -or $l -lt [int]::MinValue) { return $null }\r\n    return [int]$l\r\n}\r\n\r\nfunction ConvertTo-NullableDouble {\r\n    param($Value, [int]$Digits = 4)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [string] -and [string]::IsNullOrWhiteSpace($Value)) { return $null }\r\n    try {\r\n        $d = [double]$Value\r\n        if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }\r\n        return [math]::Round($d, $Digits)\r\n    } catch { return $null }\r\n}\r\n\r\nfunction ConvertTo-NullableBool {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [bool]) { return [bool]$Value }\r\n    $s = ([string]$Value).Trim()\r\n    if ($s -match '^(?i:true|1|yes)$') { return $true }\r\n    if ($s -match '^(?i:false|0|no)$') { return $false }\r\n    return $null\r\n}\r\n\r\nfunction ConvertTo-IsoUtc {\r\n    # ISO 8601 UTC 'yyyy-MM-ddTHH:mm:ssZ'. DateTime with Kind Unspecified is treated as LOCAL time,\r\n    # unless -AssumeUtc (values that the object model documents as UTC). Sentinels (MinValue,\r\n    # MaxValue, years before 1901 or after 9000) mean \"unknown\" and return $null.\r\n    param($Value, [switch]$AssumeUtc)\r\n    if ($null -eq $Value) { return $null }\r\n    $dt = $null\r\n    if ($Value -is [DateTimeOffset]) {\r\n        $dt = $Value.UtcDateTime\r\n    } elseif ($Value -is [datetime]) {\r\n        $dt = [datetime]$Value\r\n        if ($dt.Kind -eq [DateTimeKind]::Local) { $dt = $dt.ToUniversalTime() }\r\n        elseif ($dt.Kind -eq [DateTimeKind]::Unspecified) {\r\n            if ($AssumeUtc) { $dt = [datetime]::SpecifyKind($dt, [DateTimeKind]::Utc) } else { $dt = [datetime]::SpecifyKind($dt, [DateTimeKind]::Local).ToUniversalTime() }\r\n        }\r\n    } else {\r\n        $s = ([string]$Value).Trim()\r\n        if ($s.Length -eq 0) { return $null }\r\n        $parsed = [datetime]::MinValue\r\n        $styles = [System.Globalization.DateTimeStyles]::RoundtripKind\r\n        if (-not [datetime]::TryParse($s, $script:EP365Invariant, $styles, [ref]$parsed)) { return $null }\r\n        return (ConvertTo-IsoUtc -Value $parsed -AssumeUtc:$AssumeUtc)\r\n    }\r\n    if ($dt.Year -le 1900 -or $dt.Year -ge 9000) { return $null }\r\n    return $dt.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant)\r\n}\r\n\r\nfunction Get-UtcNowIso {\r\n    return [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant)\r\n}\r\n\r\nfunction ConvertFrom-ClaimsLogin {\r\n    # 'i:0#.w|firma\\user' -> 'firma\\user' (Windows claims only). Other claims stay as they are.\r\n    param($Login)\r\n    $s = ConvertTo-NullableString $Login\r\n    if ($null -eq $s) { return $null }\r\n    if ($s -match '^i:0[#e]\\.w\\|(.+)$') { return $Matches[1] }\r\n    return $s\r\n}\r\n\r\nfunction Get-StringList {\r\n    # Strings from a collection, without $null and empty values. Call as @(Get-StringList $x).\r\n    param($Items, [string]$Property)\r\n    foreach ($i in @($Items)) {\r\n        if ($null -eq $i) { continue }\r\n        $v = $i\r\n        if ($Property) { $v = Get-Prop -Object $i -Path $Property }\r\n        $s = ConvertTo-NullableString $v\r\n        if ($null -ne $s) { $s }\r\n    }\r\n}\r\n\r\nfunction Write-Utf8File {\r\n    # [System.IO.File] uses the .NET current directory, never the PowerShell location: absolute paths only.\r\n    param([Parameter(Mandatory = $true)][string]$Path, [AllowEmptyString()][string]$Text)\r\n    if (-not [System.IO.Path]::IsPathRooted($Path)) { throw \"Write-Utf8File needs an absolute path: $Path\" }\r\n    [System.IO.File]::WriteAllText($Path, $Text, $script:EP365Utf8NoBom)\r\n}\r\n\r\nfunction Read-Utf8File {\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    if (-not [System.IO.Path]::IsPathRooted($Path)) { throw \"Read-Utf8File needs an absolute path: $Path\" }\r\n    return [System.IO.File]::ReadAllText($Path, $script:EP365Utf8NoBom)\r\n}\r\n\r\nfunction ConvertTo-SnapshotJson {\r\n    param($InputObject)\r\n    return (ConvertTo-Json -InputObject $InputObject -Depth 20 -Compress)\r\n}\r\n\r\n# ---------- shared state and cache ----------\r\n\r\nfunction Get-Cached {\r\n    # Runs the factory once per collector run and caches the result as an array.\r\n    # Emits the items: call as @(Get-Cached 'key' { ... }).\r\n    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][scriptblock]$Factory)\r\n    $cache = $script:EP365State.Cache\r\n    if (-not $cache.ContainsKey($Key)) {\r\n        $cache[$Key] = @(& $Factory)\r\n    }\r\n    foreach ($i in $cache[$Key]) { $i }\r\n}\r\n\r\nfunction Get-CachedValue {\r\n    # Runs the factory once and caches a single value (may be $null). Returns the value itself.\r\n    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][scriptblock]$Factory)\r\n    $cache = $script:EP365State.Cache\r\n    if (-not $cache.ContainsKey($Key)) {\r\n        $cache[$Key] = (& $Factory)\r\n    }\r\n    return , $cache[$Key]\r\n}\r\n\r\n# ---------- module context, budget and errors ----------\r\n\r\nfunction New-ModuleContext {\r\n    param([Parameter(Mandatory = $true)][string]$Id, [int]$BudgetMinutes = 20)\r\n    return [pscustomobject]@{\r\n        Id              = $Id\r\n        CollectedAt     = Get-UtcNowIso\r\n        DeadlineUtc     = [DateTime]::UtcNow.AddMinutes($BudgetMinutes)\r\n        BudgetMinutes   = $BudgetMinutes\r\n        Errors          = New-Object System.Collections.Generic.List[object]\r\n        BudgetExhausted = $false\r\n        PartialReason   = $null\r\n        SkipReason      = $null\r\n    }\r\n}\r\n\r\nfunction Add-ModuleError {\r\n    param([Parameter(Mandatory = $true)]$Ctx, [string]$Scope, $ErrorObject)\r\n    $msg = Format-ErrorText $ErrorObject\r\n    if ([string]::IsNullOrWhiteSpace($Scope)) { $Scope = $Ctx.Id }\r\n    $Ctx.Errors.Add([pscustomobject][ordered]@{ scope = [string]$Scope; message = $msg })\r\n    Write-CollectorLog -Level WARN -Message ('{0}: {1}: {2}' -f $Ctx.Id, $Scope, $msg)\r\n}\r\n\r\nfunction Test-ModuleBudget {\r\n    # $true while the module still has time; sets BudgetExhausted once the budget is used up.\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    if ([DateTime]::UtcNow -lt $Ctx.DeadlineUtc) { return $true }\r\n    if (-not $Ctx.BudgetExhausted) {\r\n        $Ctx.BudgetExhausted = $true\r\n        Write-CollectorLog -Level WARN -Message ('{0}: time budget of {1} min exhausted, the result is partial' -f $Ctx.Id, $Ctx.BudgetMinutes)\r\n    }\r\n    return $false\r\n}\r\n\r\nfunction Get-RemainingSeconds {\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    $s = [int][math]::Floor(($Ctx.DeadlineUtc - [DateTime]::UtcNow).TotalSeconds)\r\n    if ($s -lt 1) { return 1 }\r\n    return $s\r\n}\r\n\r\nfunction Get-ModuleFunctionName {\r\n    param([string]$Id)\r\n    $map = @{\r\n        farm = 'Get-FarmModuleData'; webapps = 'Get-WebAppsModuleData'; sites = 'Get-SitesModuleData'\r\n        usage = 'Get-UsageModuleData'; databases = 'Get-DatabasesModuleData'; services = 'Get-ServicesModuleData'\r\n        security = 'Get-SecurityModuleData'; search = 'Get-SearchModuleData'; iis = 'Get-IisModuleData'\r\n        perf = 'Get-PerfModuleData'; events = 'Get-EventsModuleData'; deep = 'Get-DeepModuleData'\r\n    }\r\n    return $map[$Id]\r\n}\r\n\r\nfunction Invoke-CollectorModule {\r\n    # Runs one module with its own time budget and error isolation. Returns the manifest entry.\r\n    # The module function returns @{ Data = <object>; Records = <int|null> } (or throws = failed).\r\n    param([Parameter(Mandatory = $true)][string]$Id, [int]$BudgetMinutes = 20)\r\n    $sw = [System.Diagnostics.Stopwatch]::StartNew()\r\n    $ctx = New-ModuleContext -Id $Id -BudgetMinutes $BudgetMinutes\r\n    $entry = [ordered]@{ id = $Id; file = $null; status = 'failed'; durationSec = 0; records = $null; error = $null }\r\n    Write-CollectorLog -Message ('Module {0}: start (budget {1} min)' -f $Id, $BudgetMinutes)\r\n    try {\r\n        $fn = Get-ModuleFunctionName $Id\r\n        $result = & $fn -Ctx $ctx\r\n        if ($result -is [array]) {\r\n            # Stray pipeline output inside a module function; keep the module result itself.\r\n            Write-CollectorLog -Level WARN -Message ('Module {0}: unexpected extra output ignored' -f $Id)\r\n            $result = @($result | Where-Object { $_ -is [System.Collections.IDictionary] -and $_.Contains('Data') }) | Select-Object -Last 1\r\n        }\r\n        if ($null -ne $ctx.SkipReason) {\r\n            $entry.status = 'skipped'\r\n            $entry.error = $ctx.SkipReason\r\n        } else {\r\n            $fileName = $Id + '.json'\r\n            Save-ModuleFile -Ctx $ctx -Data $result.Data -FileName $fileName\r\n            $entry.file = $fileName\r\n            $entry.records = ConvertTo-NullableInt $result.Records\r\n            if ($ctx.BudgetExhausted -or $ctx.Errors.Count -gt 0 -or $null -ne $ctx.PartialReason) {\r\n                $entry.status = 'partial'\r\n                $parts = New-Object System.Collections.Generic.List[string]\r\n                if ($ctx.BudgetExhausted) { $parts.Add(('Time budget of {0} min exhausted' -f $ctx.BudgetMinutes)) }\r\n                if ($null -ne $ctx.PartialReason) { $parts.Add([string]$ctx.PartialReason) }\r\n                if ($ctx.Errors.Count -gt 0) { $parts.Add(('{0} non-fatal error(s), first: {1}: {2}' -f $ctx.Errors.Count, $ctx.Errors[0].scope, $ctx.Errors[0].message)) }\r\n                $entry.error = Format-ErrorText ($parts -join '; ')\r\n            } else {\r\n                $entry.status = 'ok'\r\n            }\r\n        }\r\n    } catch {\r\n        $entry.status = 'failed'\r\n        $entry.file = $null\r\n        $entry.records = $null\r\n        $entry.error = Format-ErrorText $_\r\n        Write-CollectorLog -Level ERROR -Message ('Module {0} failed: {1}' -f $Id, $entry.error)\r\n    }\r\n    $sw.Stop()\r\n    $entry.durationSec = [math]::Round($sw.Elapsed.TotalSeconds, 1)\r\n    Write-CollectorLog -Message ('Module {0}: {1} in {2} s' -f $Id, $entry.status, $entry.durationSec)\r\n    return [pscustomobject]$entry\r\n}\r\n\r\nfunction Save-ModuleFile {\r\n    # Writes IModuleFile<T>: schemaVersion, module, collectedAt, errors, data.\r\n    param([Parameter(Mandatory = $true)]$Ctx, $Data, [Parameter(Mandatory = $true)][string]$FileName)\r\n    $wrapper = [ordered]@{\r\n        schemaVersion = $script:EP365SchemaVersion\r\n        module        = $Ctx.Id\r\n        collectedAt   = $Ctx.CollectedAt\r\n        errors        = @($Ctx.Errors.ToArray())\r\n        data          = $Data\r\n    }\r\n    $json = ConvertTo-SnapshotJson $wrapper\r\n    Write-Utf8File -Path (Join-Path $script:EP365State.WorkDir $FileName) -Text $json\r\n    if ($script:EP365State.Anonymize) {\r\n        try { Add-AnonymizationHarvest -ModuleId $Ctx.Id -Data $Data -JsonText $json }\r\n        catch { Write-CollectorLog -Level WARN -Message ('Anonymization harvest of {0} failed: {1}' -f $Ctx.Id, (Format-ErrorText $_)) }\r\n    }\r\n}\r\n\r\nfunction Save-Manifest {\r\n    param([Parameter(Mandatory = $true)]$Manifest)\r\n    $json = ConvertTo-SnapshotJson $Manifest\r\n    Write-Utf8File -Path (Join-Path $script:EP365State.WorkDir 'manifest.json') -Text $json\r\n}\r\n\r\n# ===================== 55-Graph: certificate sign-in and Microsoft Graph requests to the Inbox =====================\r\n#\r\n# Automatic mode only. The collector application has ONE permission:\r\n# ListItems.SelectedOperations.Selected with the role 'write' on ONE item - the folder Inbox of the\r\n# Atlas snapshot library. It cannot read the site, the library or the stored snapshots, so every\r\n# request addresses the Inbox folder by its driveItem id (stored by -Install) and paths relative\r\n# to it. Test-GraphTarget enforces that before any request leaves the server.\r\n\r\n$script:EP365GraphHost = 'graph.microsoft.com'\r\n$script:EP365LoginHost = 'login.microsoftonline.com'\r\n# Files up to this size go in one PUT (Microsoft: resumable upload above 10 MiB); bigger ones\r\n# through an upload session in fragments that are a multiple of 320 KiB (10 MiB = 32 x 320 KiB).\r\n$script:EP365SimpleUploadMaxBytes = 10485760\r\n$script:EP365UploadFragmentBytes = 10485760\r\n$script:EP365HttpMaxAttempts = 5\r\n# Graph session of this run: @{ Config; Certificate; Token; ExpiresUtc }. The token never goes to a log.\r\n$script:EP365Graph = $null\r\n\r\nfunction ConvertTo-Base64Url {\r\n    param([byte[]]$Bytes)\r\n    return ([Convert]::ToBase64String($Bytes)).TrimEnd('=').Replace('+', '-').Replace('/', '_')\r\n}\r\n\r\nfunction ConvertFrom-Base64Url {\r\n    param([string]$Text)\r\n    $s = $Text.Replace('-', '+').Replace('_', '/')\r\n    switch ($s.Length % 4) { 2 { $s += '==' } 3 { $s += '=' } }\r\n    return [Convert]::FromBase64String($s)\r\n}\r\n\r\nfunction ConvertFrom-HexString {\r\n    param([string]$Hex)\r\n    $clean = ($Hex -replace '[^0-9A-Fa-f]', '')\r\n    $bytes = New-Object byte[] ($clean.Length / 2)\r\n    for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($clean.Substring($i * 2, 2), 16) }\r\n    return , $bytes\r\n}\r\n\r\nfunction Test-TenantIdText { param([string]$Value) return ($Value -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') }\r\n\r\nfunction Get-TokenUrl {\r\n    param([Parameter(Mandatory = $true)][string]$TenantId)\r\n    if (-not (Test-TenantIdText $TenantId)) { throw ('Tenant id must be a GUID: ' + $TenantId) }\r\n    return ('https://' + $script:EP365LoginHost + '/' + $TenantId.ToLowerInvariant() + '/oauth2/v2.0/token')\r\n}\r\n\r\nfunction New-ClientAssertion {\r\n    # JWT client assertion signed with the certificate (Microsoft identity platform, certificate\r\n    # credentials): header alg PS256 + x5t#S256 (SHA-256 of the DER certificate), claims aud, exp,\r\n    # iss, jti, nbf, sub, iat. Keys that cannot sign with PSS (legacy CSP) fall back to RS256 + x5t.\r\n    param(\r\n        [Parameter(Mandatory = $true)][System.Security.Cryptography.X509Certificates.X509Certificate2]$Certificate,\r\n        [Parameter(Mandatory = $true)][string]$TenantId,\r\n        [Parameter(Mandatory = $true)][string]$ClientId,\r\n        [datetime]$NowUtc = [DateTime]::UtcNow,\r\n        [string]$JwtId,\r\n        [switch]$ForceRs256\r\n    )\r\n    $rsa = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($Certificate)\r\n    if ($null -eq $rsa) { throw 'The certificate has no RSA private key that this account can use' }\r\n    $epoch = New-Object DateTime (1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc)\r\n    $nbf = [long][math]::Floor(($NowUtc.ToUniversalTime() - $epoch).TotalSeconds)\r\n    if (-not $JwtId) { $JwtId = [guid]::NewGuid().ToString() }\r\n    $claims = [ordered]@{ aud = (Get-TokenUrl $TenantId); exp = ($nbf + 600); iss = $ClientId; jti = $JwtId; nbf = $nbf; sub = $ClientId; iat = $nbf }\r\n    $claimsB64 = ConvertTo-Base64Url ([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $claims -Compress)))\r\n    $sha256 = [System.Security.Cryptography.SHA256]::Create()\r\n    $variants = @(\r\n        @{ Header = [ordered]@{ alg = 'PS256'; typ = 'JWT'; 'x5t#S256' = (ConvertTo-Base64Url ($sha256.ComputeHash($Certificate.RawData))) }; Padding = [System.Security.Cryptography.RSASignaturePadding]::Pss },\r\n        @{ Header = [ordered]@{ alg = 'RS256'; typ = 'JWT'; x5t = (ConvertTo-Base64Url (ConvertFrom-HexString $Certificate.Thumbprint)) }; Padding = [System.Security.Cryptography.RSASignaturePadding]::Pkcs1 }\r\n    )\r\n    if ($ForceRs256) { $variants = @($variants[1]) }\r\n    $lastError = $null\r\n    foreach ($v in $variants) {\r\n        $headerB64 = ConvertTo-Base64Url ([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $v.Header -Compress)))\r\n        $signingInput = $headerB64 + '.' + $claimsB64\r\n        try {\r\n            $sig = $rsa.SignData([Text.Encoding]::ASCII.GetBytes($signingInput), [System.Security.Cryptography.HashAlgorithmName]::SHA256, $v.Padding)\r\n            return ($signingInput + '.' + (ConvertTo-Base64Url $sig))\r\n        } catch {\r\n            $lastError = $_\r\n        }\r\n    }\r\n    throw ('The certificate key cannot sign the sign-in assertion: ' + (Format-ErrorText $lastError))\r\n}\r\n\r\n# ---------- the only network access of the collector ----------\r\n\r\nfunction Invoke-HttpRaw {\r\n    # One HTTPS request. Returns @{ Status; Headers (lower-case names); Text; Bytes }. HTTP error\r\n    # statuses are returned, transport errors (DNS, TLS, proxy, timeout) throw. Tests replace it.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$Method,\r\n        [Parameter(Mandatory = $true)][string]$Uri,\r\n        [hashtable]$Headers,\r\n        [byte[]]$Body,\r\n        [string]$ContentType,\r\n        [int]$TimeoutSec = 300,\r\n        # SharePoint REST of the access collector asks for odata=nometadata (Accept cannot go through -Headers).\r\n        [string]$Accept = 'application/json'\r\n    )\r\n    $req = [System.Net.HttpWebRequest]::Create($Uri)\r\n    $req.Method = $Method\r\n    $req.Timeout = $TimeoutSec * 1000\r\n    $req.ReadWriteTimeout = $TimeoutSec * 1000\r\n    $req.AllowAutoRedirect = $true\r\n    $req.UserAgent = 'EP365AtlasCollector/' + $script:EP365CollectorVersion\r\n    $req.Accept = $Accept\r\n    $proxyUrl = $null\r\n    if ($null -ne $script:EP365Graph -and $null -ne $script:EP365Graph.Config) { $proxyUrl = ConvertTo-NullableString (Get-Prop $script:EP365Graph.Config 'proxy') }\r\n    if ($proxyUrl) {\r\n        $wp = New-Object System.Net.WebProxy ($proxyUrl, $true)\r\n        $wp.UseDefaultCredentials = $true\r\n        $req.Proxy = $wp\r\n    } else {\r\n        $sys = [System.Net.WebRequest]::GetSystemWebProxy()\r\n        $sys.Credentials = [System.Net.CredentialCache]::DefaultNetworkCredentials\r\n        $req.Proxy = $sys\r\n    }\r\n    if ($Headers) { foreach ($k in $Headers.Keys) { $req.Headers[$k] = [string]$Headers[$k] } }\r\n    if ($ContentType) { $req.ContentType = $ContentType }\r\n    if ($null -ne $Body) {\r\n        $req.ContentLength = $Body.Length\r\n        $rs = $req.GetRequestStream()\r\n        try { $rs.Write($Body, 0, $Body.Length) } finally { $rs.Close() }\r\n    } elseif ($Method -eq 'PUT' -or $Method -eq 'POST') {\r\n        $req.ContentLength = 0\r\n    }\r\n    $resp = $null\r\n    try {\r\n        $resp = $req.GetResponse()\r\n    } catch {\r\n        $we = $_.Exception\r\n        while ($null -ne $we -and -not ($we -is [System.Net.WebException])) { $we = $we.InnerException }\r\n        if ($null -eq $we -or $null -eq $we.Response) { throw }\r\n        $resp = $we.Response\r\n    }\r\n    try {\r\n        $headersOut = @{}\r\n        foreach ($k in $resp.Headers.AllKeys) { $headersOut[$k.ToLowerInvariant()] = $resp.Headers[$k] }\r\n        $ms = New-Object System.IO.MemoryStream\r\n        $stream = $resp.GetResponseStream()\r\n        if ($null -ne $stream) { try { $stream.CopyTo($ms) } finally { $stream.Close() } }\r\n        $bytes = $ms.ToArray()\r\n        return @{ Status = [int]$resp.StatusCode; Headers = $headersOut; Bytes = $bytes; Text = [Text.Encoding]::UTF8.GetString($bytes) }\r\n    } finally {\r\n        $resp.Close()\r\n    }\r\n}\r\n\r\nfunction Start-CollectorSleep {\r\n    # Wait between retries (tests replace it to record the waits).\r\n    param([int]$Seconds)\r\n    Start-Sleep -Seconds $Seconds\r\n}\r\n\r\nfunction Initialize-CollectorNetwork {\r\n    # TLS 1.2 for login.microsoftonline.com and graph.microsoft.com (Windows PowerShell 5.1 may\r\n    # default to older protocols on servers without the .NET strong-crypto settings).\r\n    [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls12\r\n}\r\n\r\nfunction Get-InboxIds {\r\n    # Drive id of the snapshot library and driveItem id of its Inbox folder from the configuration;\r\n    # $null when either is missing or not a plain id.\r\n    $cfg = $null\r\n    if ($null -ne $script:EP365Graph) { $cfg = $script:EP365Graph.Config }\r\n    $driveId = ConvertTo-NullableString (Get-Prop $cfg 'driveId')\r\n    $inboxId = ConvertTo-NullableString (Get-Prop $cfg 'inboxItemId')\r\n    if ($null -eq $driveId -or $driveId -notmatch '^[A-Za-z0-9!_-]+$') { return $null }\r\n    if ($null -eq $inboxId -or $inboxId -notmatch '^[A-Za-z0-9!_-]+$') { return $null }\r\n    return @{ DriveId = $driveId; InboxId = $inboxId }\r\n}\r\n\r\nfunction Test-GraphTarget {\r\n    # $true when the request is one the collector may send: sign-in, the Inbox folder of the\r\n    # snapshot library (addressed by its item id - the application has a role on that folder\r\n    # only), or the upload session URL Graph handed out (SharePoint host).\r\n    param([string]$Method, [string]$Uri, [bool]$NoAuth)\r\n    $u = $null\r\n    if (-not [Uri]::TryCreate($Uri, [UriKind]::Absolute, [ref]$u)) { return $false }\r\n    if ($u.Scheme -ne 'https') { return $false }\r\n    $hostName = $u.Host.ToLowerInvariant()\r\n    $path = $u.AbsolutePath\r\n    if ($hostName -eq $script:EP365LoginHost) {\r\n        return ($Method -eq 'POST' -and $NoAuth -and $path -match '^/[0-9a-f-]{36}/oauth2/v2\\.0/token$')\r\n    }\r\n    if ($hostName -match '^[a-z0-9-]+\\.sharepoint\\.com$') {\r\n        # Only the pre-authenticated upload session URL Graph handed out in this run: fragments (PUT),\r\n        # status (GET), cancel (DELETE); never with a token.\r\n        $known = ($null -ne $script:EP365Graph -and $null -ne $script:EP365Graph.SessionUrls -and $script:EP365Graph.SessionUrls.ContainsKey($Uri))\r\n        return ($NoAuth -and $known -and @('PUT', 'GET', 'DELETE') -contains $Method)\r\n    }\r\n    if ($hostName -ne $script:EP365GraphHost -or $NoAuth) { return $false }\r\n    # -TestConnection only: the least-privilege probes (GET outside the Inbox that MUST be refused)\r\n    # are allowed by exact URL while Test-LeastPrivilege runs, never otherwise.\r\n    if ($Method -eq 'GET' -and $null -ne $script:EP365Graph -and $null -ne $script:EP365Graph.ProbeUrls -and $script:EP365Graph.ProbeUrls.ContainsKey($Uri)) { return $true }\r\n    $ids = Get-InboxIds\r\n    if ($null -eq $ids) { return $false }\r\n    $root = '/v1.0/drives/' + $ids.DriveId + '/items/' + $ids.InboxId\r\n    $raw = $u.OriginalString.Substring($u.GetLeftPart([UriPartial]::Authority).Length)\r\n    $q = $raw.IndexOf('?')\r\n    if ($q -ge 0) { $raw = $raw.Substring(0, $q) }\r\n    if (-not $raw.StartsWith($root, [StringComparison]::Ordinal)) { return $false }\r\n    # No way out of the Inbox: no dot segments, no encoded dots or separators.\r\n    if ($raw -match '(^|/)\\.{1,2}(/|:|$)' -or $raw -match '(?i)%2e|%2f|%5c|\\\\') { return $false }\r\n    $rest = $raw.Substring($root.Length)\r\n    $inside = $rest.StartsWith(':/', [StringComparison]::Ordinal)\r\n    # GET may read the Inbox folder itself; PUT and DELETE only touch items INSIDE it; POST only\r\n    # creates a folder of a farm in it or an upload session for a file inside it.\r\n    if ($Method -eq 'GET') { return ($rest -eq '' -or $inside) }\r\n    if ($Method -eq 'PUT' -or $Method -eq 'DELETE') { return ($inside -and $rest.Length -gt 2) }\r\n    if ($Method -eq 'POST') {\r\n        if ($rest -eq '/children') { return $true }\r\n        return ($inside -and $rest.EndsWith(':/createUploadSession', [StringComparison]::Ordinal))\r\n    }\r\n    return $false\r\n}\r\n\r\nfunction Get-GraphInboxUrl {\r\n    # https://graph.microsoft.com/v1.0/drives/<driveId>/items/<inboxItemId>[:/<segments><suffix>]\r\n    # The Inbox folder is addressed by its driveItem id; files and the farm folders by a path\r\n    # relative to it. Segments are file and folder names only (no '..', no separators inside).\r\n    param([string]$RelPath = '', [string]$Suffix = '', [switch]$Children)\r\n    $ids = Get-InboxIds\r\n    if ($null -eq $ids) { throw 'The drive id of the snapshot library or the item id of its Inbox folder is missing or invalid in the configuration (run -Install again with the values from Register-EP365AtlasCollectorApp.ps1)' }\r\n    $base = 'https://' + $script:EP365GraphHost + '/v1.0/drives/' + $ids.DriveId + '/items/' + $ids.InboxId\r\n    $segs = @($RelPath -split '/' | Where-Object { $_ -ne '' })\r\n    if ($Children) {\r\n        if ($segs.Count -gt 0) { throw 'Children of a subfolder are not used' }\r\n        return ($base + '/children')\r\n    }\r\n    if ($segs.Count -eq 0) { return $base }\r\n    $path = ''\r\n    foreach ($seg in $segs) {\r\n        if ($seg -notmatch '^[A-Za-z0-9._-]+$' -or $seg -eq '.' -or $seg -eq '..') { throw ('Invalid name in the Inbox path: ' + $seg) }\r\n        if ($path) { $path += '/' }\r\n        $path += [Uri]::EscapeDataString($seg)\r\n    }\r\n    return ($base + ':/' + $path + $Suffix)\r\n}\r\n\r\nfunction Get-RetryAfterSeconds {\r\n    param($Response)\r\n    if ($null -eq $Response -or $null -eq $Response.Headers) { return 0 }\r\n    $v = [string]$Response.Headers['retry-after']\r\n    if ([string]::IsNullOrWhiteSpace($v)) { return 0 }\r\n    $n = 0\r\n    if ([int]::TryParse($v.Trim(), [ref]$n)) { return [math]::Max(0, $n) }\r\n    $d = [DateTime]::MinValue\r\n    if ([DateTime]::TryParse($v, $script:EP365Invariant, [System.Globalization.DateTimeStyles]::AdjustToUniversal, [ref]$d)) {\r\n        return [int][math]::Max(0, [math]::Ceiling(($d - [DateTime]::UtcNow).TotalSeconds))\r\n    }\r\n    return 0\r\n}\r\n\r\nfunction Get-GraphErrorText {\r\n    param($Response)\r\n    if ($null -eq $Response) { return 'no response' }\r\n    $msg = $null\r\n    try {\r\n        $j = ConvertFrom-Json -InputObject $Response.Text\r\n        $msg = ConvertTo-NullableString (Get-Prop $j 'error.message')\r\n        if ($null -eq $msg) { $msg = ConvertTo-NullableString (Get-Prop $j 'error_description') }\r\n        if ($null -eq $msg) { $msg = ConvertTo-NullableString (Get-Prop $j 'error.code') }\r\n    } catch { }\r\n    if ($null -eq $msg) { $msg = 'HTTP ' + $Response.Status }\r\n    return (Format-ErrorText ('HTTP ' + $Response.Status + ': ' + $msg))\r\n}\r\n\r\nfunction Invoke-GraphRequest {\r\n    # Guarded request with retries: 429 and 5xx wait for Retry-After (or 2, 4, 8 ... s, at most\r\n    # 5 minutes), a transport error is retried, 401 renews the token once. Returns the response\r\n    # (callers decide which statuses are success); throws when the request is not allowed or the\r\n    # network never answered.\r\n    param(\r\n        [Parameter(Mandatory = $true)][ValidateSet('GET', 'PUT', 'POST', 'DELETE')][string]$Method,\r\n        [Parameter(Mandatory = $true)][string]$Uri,\r\n        [byte[]]$Body,\r\n        [string]$ContentType,\r\n        [hashtable]$Headers,\r\n        [switch]$NoAuth,\r\n        [int]$MaxAttempts = $script:EP365HttpMaxAttempts\r\n    )\r\n    if (-not (Test-GraphTarget -Method $Method -Uri $Uri -NoAuth ([bool]$NoAuth))) {\r\n        throw ('Blocked: the collector may not send {0} {1}' -f $Method, ($Uri -replace '\\?.*$', ''))\r\n    }\r\n    $renewed = $false\r\n    for ($attempt = 1; ; $attempt++) {\r\n        $h = @{}\r\n        if ($Headers) { foreach ($k in $Headers.Keys) { $h[$k] = $Headers[$k] } }\r\n        if (-not $NoAuth) { $h['Authorization'] = 'Bearer ' + (Get-GraphAccessToken) }\r\n        $resp = $null\r\n        $transport = $null\r\n        try { $resp = Invoke-HttpRaw -Method $Method -Uri $Uri -Headers $h -Body $Body -ContentType $ContentType }\r\n        catch { $transport = Format-ErrorText $_ }\r\n        $wait = 0\r\n        $retry = $false\r\n        if ($null -ne $transport) { $retry = $true }\r\n        elseif ($resp.Status -eq 429 -or $resp.Status -ge 500) { $retry = $true; $wait = Get-RetryAfterSeconds $resp }\r\n        elseif ($resp.Status -eq 401 -and -not $NoAuth -and -not $renewed) { $retry = $true; $renewed = $true; $script:EP365Graph.Token = $null }\r\n        if (-not $retry -or $attempt -ge $MaxAttempts) {\r\n            if ($null -ne $transport) { throw ('Network error ({0} {1}): {2}' -f $Method, ($Uri -replace '\\?.*$', ''), $transport) }\r\n            return $resp\r\n        }\r\n        if ($wait -le 0 -and ($null -eq $resp -or $resp.Status -ne 401)) { $wait = [int][math]::Pow(2, $attempt) }\r\n        if ($wait -gt 300) { $wait = 300 }\r\n        $why = $transport\r\n        if ($null -eq $why) { $why = 'HTTP ' + $resp.Status }\r\n        Write-CollectorLog -Level WARN -Message ('{0} {1}: {2}, attempt {3} of {4}, next in {5} s' -f $Method, ($Uri -replace '\\?.*$', ''), $why, $attempt, $MaxAttempts, $wait)\r\n        if ($wait -gt 0) { Start-CollectorSleep -Seconds $wait }\r\n    }\r\n}\r\n\r\nfunction Initialize-GraphSession {\r\n    param([Parameter(Mandatory = $true)]$Config, [Parameter(Mandatory = $true)]$Certificate)\r\n    Initialize-CollectorNetwork\r\n    $script:EP365Graph = @{ Config = $Config; Certificate = $Certificate; Token = $null; ExpiresUtc = [DateTime]::MinValue; SessionUrls = @{}; ProbeUrls = @{} }\r\n}\r\n\r\nfunction Get-GraphAccessToken {\r\n    # Client credentials with the certificate assertion; cached for the run (renewed 5 minutes early).\r\n    $g = $script:EP365Graph\r\n    if ($null -eq $g) { throw 'The Graph session is not initialized' }\r\n    if ($g.Token -and [DateTime]::UtcNow -lt $g.ExpiresUtc) { return $g.Token }\r\n    $tenant = [string](Get-Prop $g.Config 'tenantId')\r\n    $client = [string](Get-Prop $g.Config 'clientId')\r\n    $jwt = New-ClientAssertion -Certificate $g.Certificate -TenantId $tenant -ClientId $client\r\n    $form = 'client_id=' + [Uri]::EscapeDataString($client) +\r\n        '&scope=' + [Uri]::EscapeDataString('https://' + $script:EP365GraphHost + '/.default') +\r\n        '&client_assertion_type=' + [Uri]::EscapeDataString('urn:ietf:params:oauth:client-assertion-type:jwt-bearer') +\r\n        '&client_assertion=' + [Uri]::EscapeDataString($jwt) +\r\n        '&grant_type=client_credentials'\r\n    $r = Invoke-GraphRequest -Method POST -Uri (Get-TokenUrl $tenant) -Body ([Text.Encoding]::ASCII.GetBytes($form)) -ContentType 'application/x-www-form-urlencoded' -NoAuth\r\n    if ($r.Status -ne 200) { throw ('Sign-in of the collector application failed: ' + (Get-GraphErrorText $r)) }\r\n    $j = ConvertFrom-Json -InputObject $r.Text\r\n    $token = ConvertTo-NullableString (Get-Prop $j 'access_token')\r\n    if ($null -eq $token) { throw 'Sign-in of the collector application returned no access token' }\r\n    $life = ConvertTo-NullableInt (Get-Prop $j 'expires_in')\r\n    if ($null -eq $life -or $life -lt 600) { $life = 600 }\r\n    $g.Token = $token\r\n    $g.ExpiresUtc = [DateTime]::UtcNow.AddSeconds($life - 300)\r\n    return $token\r\n}\r\n\r\n# ---------- Inbox operations ----------\r\n\r\nfunction Confirm-InboxFolder {\r\n    # Creates Inbox/<farm id> when it is missing (201 = created, 409 = exists). The Inbox folder\r\n    # itself is created by the registration (the application has no right outside it).\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $body = ConvertTo-Json -Compress -InputObject ([ordered]@{ name = $SpFarmId; folder = @{}; '@microsoft.graph.conflictBehavior' = 'fail' })\r\n    $r = Invoke-GraphRequest -Method POST -Uri (Get-GraphInboxUrl -Children) -Body ([Text.Encoding]::UTF8.GetBytes($body)) -ContentType 'application/json'\r\n    if ($r.Status -eq 201 -or $r.Status -eq 200 -or $r.Status -eq 409) { return }\r\n    if ($r.Status -eq 404) { throw ('The Inbox folder of the snapshot library was not found by its id (deleted or recreated?). Run Register-EP365AtlasCollectorApp.ps1 again and -Install with the new -InboxItemId. ' + (Get-GraphErrorText $r)) }\r\n    throw ('Folder ' + $SpFarmId + ' in the Inbox cannot be created: ' + (Get-GraphErrorText $r))\r\n}\r\n\r\nfunction Test-UploadedItem {\r\n    # The driveItem Graph returned for an upload must be the file with the local size.\r\n    param($Response, [long]$Length, [string]$Name)\r\n    try { $j = ConvertFrom-Json -InputObject $Response.Text } catch { throw ('Upload of ' + $Name + ' returned an unreadable answer') }\r\n    $size = ConvertTo-NullableLong (Get-Prop $j 'size')\r\n    if ($size -ne $Length) { throw ('Upload of {0} is not complete: {1} bytes in the library, {2} bytes locally' -f $Name, $size, $Length) }\r\n    return (ConvertTo-NullableString (Get-Prop $j 'id'))\r\n}\r\n\r\nfunction Send-InboxFile {\r\n    # Uploads a local file to Inbox/<farm id>/<name>. Returns the driveItem id; throws on failure\r\n    # (the caller keeps the file in the queue).\r\n    param([Parameter(Mandatory = $true)][string]$Path, [Parameter(Mandatory = $true)][string]$SpFarmId, [string]$Name)\r\n    if (-not $Name) { $Name = [System.IO.Path]::GetFileName($Path) }\r\n    $length = (New-Object System.IO.FileInfo $Path).Length\r\n    $rel = $SpFarmId + '/' + $Name\r\n    for ($pass = 1; $pass -le 2; $pass++) {\r\n        if ($length -le $script:EP365SimpleUploadMaxBytes) {\r\n            $r = Invoke-GraphRequest -Method PUT -Uri (Get-GraphInboxUrl -RelPath $rel -Suffix ':/content') -Body ([System.IO.File]::ReadAllBytes($Path)) -ContentType 'application/octet-stream'\r\n            if ($r.Status -eq 200 -or $r.Status -eq 201) { return (Test-UploadedItem -Response $r -Length $length -Name $Name) }\r\n            if ($r.Status -eq 404 -and $pass -eq 1) { Confirm-InboxFolder -SpFarmId $SpFarmId; continue }\r\n            throw ('Upload of ' + $Name + ' failed: ' + (Get-GraphErrorText $r))\r\n        }\r\n        $body = ConvertTo-Json -Compress -InputObject ([ordered]@{ item = [ordered]@{ '@microsoft.graph.conflictBehavior' = 'replace' } })\r\n        $s = Invoke-GraphRequest -Method POST -Uri (Get-GraphInboxUrl -RelPath $rel -Suffix ':/createUploadSession') -Body ([Text.Encoding]::UTF8.GetBytes($body)) -ContentType 'application/json'\r\n        if ($s.Status -eq 404 -and $pass -eq 1) { Confirm-InboxFolder -SpFarmId $SpFarmId; continue }\r\n        if ($s.Status -ne 200) { throw ('Upload session for ' + $Name + ' cannot be created: ' + (Get-GraphErrorText $s)) }\r\n        $uploadUrl = ConvertTo-NullableString (Get-Prop (ConvertFrom-Json -InputObject $s.Text) 'uploadUrl')\r\n        if ($null -eq $uploadUrl) { throw ('Upload session for ' + $Name + ' has no upload URL') }\r\n        $script:EP365Graph.SessionUrls[$uploadUrl] = $true\r\n        $fs = [System.IO.File]::OpenRead($Path)\r\n        try {\r\n            $offset = [long]0\r\n            $buffer = New-Object byte[] $script:EP365UploadFragmentBytes\r\n            while ($offset -lt $length) {\r\n                $want = [int][math]::Min([long]$buffer.Length, $length - $offset)\r\n                $read = 0\r\n                while ($read -lt $want) { $n = $fs.Read($buffer, $read, $want - $read); if ($n -le 0) { break }; $read += $n }\r\n                if ($read -ne $want) { throw ('Reading ' + $Name + ' failed') }\r\n                $chunk = New-Object byte[] $want\r\n                [Array]::Copy($buffer, $chunk, $want)\r\n                $range = 'bytes {0}-{1}/{2}' -f $offset, ($offset + $want - 1), $length\r\n                $p = Invoke-GraphRequest -Method PUT -Uri $uploadUrl -Body $chunk -ContentType 'application/octet-stream' -Headers @{ 'Content-Range' = $range } -NoAuth\r\n                if ($p.Status -eq 202) { $offset += $want; continue }\r\n                if (($p.Status -eq 200 -or $p.Status -eq 201) -and ($offset + $want) -eq $length) { return (Test-UploadedItem -Response $p -Length $length -Name $Name) }\r\n                try { [void](Invoke-GraphRequest -Method DELETE -Uri $uploadUrl -NoAuth -MaxAttempts 1) } catch { }\r\n                throw ('Upload of {0} failed at byte {1}: {2}' -f $Name, $offset, (Get-GraphErrorText $p))\r\n            }\r\n        } finally {\r\n            $fs.Close()\r\n        }\r\n        throw ('Upload of ' + $Name + ' ended without the final answer')\r\n    }\r\n    throw ('Upload of ' + $Name + ' failed: the Inbox folder could not be prepared')\r\n}\r\n\r\nfunction Get-CollectRequest {\r\n    # \"Collect now\" written by Atlas: Inbox/<farm id>/request.json. $null = no request.\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $r = Invoke-GraphRequest -Method GET -Uri (Get-GraphInboxUrl -RelPath ($SpFarmId + '/request.json'))\r\n    if ($r.Status -eq 404) { return $null }\r\n    if ($r.Status -ne 200) { throw ('Reading request.json failed: ' + (Get-GraphErrorText $r)) }\r\n    $j = ConvertFrom-Json -InputObject $r.Text\r\n    return [pscustomobject]@{\r\n        at = ConvertTo-IsoUtc (Get-Prop $j 'createdDateTime')\r\n        by = ConvertTo-NullableString (Get-Prop $j 'createdBy.user.displayName')\r\n    }\r\n}\r\n\r\nfunction Clear-CollectRequest {\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $r = Invoke-GraphRequest -Method DELETE -Uri (Get-GraphInboxUrl -RelPath ($SpFarmId + '/request.json'))\r\n    if ($r.Status -ne 204 -and $r.Status -ne 200 -and $r.Status -ne 404) { throw ('Deleting request.json failed: ' + (Get-GraphErrorText $r)) }\r\n}\r\n\r\nfunction Test-InboxAccess {\r\n    # Sign-in + read of the Inbox folder. Returns a one-line verdict; throws when access is missing.\r\n    $r = Invoke-GraphRequest -Method GET -Uri (Get-GraphInboxUrl)\r\n    if ($r.Status -eq 200) { return 'Signed in; the Inbox folder of the snapshot library is reachable.' }\r\n    if ($r.Status -eq 404) {\r\n        throw ('Signed in, but the Inbox folder was not found by its id (' + (Get-GraphErrorText $r) + '). Check -InboxItemId; when the folder was deleted, run Register-EP365AtlasCollectorApp.ps1 again.')\r\n    }\r\n    if ($r.Status -eq 403 -or $r.Status -eq 401) {\r\n        throw ('Signed in, but the Inbox folder refused access (' + (Get-GraphErrorText $r) + '). Check that Register-EP365AtlasCollectorApp.ps1 granted the write role on the Inbox folder and that the admin consent exists; both can take a few minutes to apply.')\r\n    }\r\n    throw ('The snapshot library cannot be reached: ' + (Get-GraphErrorText $r))\r\n}\r\n\r\n# ===================== 56-Queue: collector folder, state and the local queue of snapshots =====================\r\n#\r\n# Automatic mode keeps everything in one folder (default C:\\ProgramData\\EP365Atlas):\r\n#   collector.json      configuration written by -Install (no secrets: ids incl. the Inbox folder, thumbprint, schedule)\r\n#   certificate.json    the certificate created by -NewCertificate (thumbprint, validity, .cer file)\r\n#   state.json          farm id, last upload, last error, last \"Collect now\" request\r\n#   farm-servers.json   SharePoint servers of the farm (the 15-minute task does not load SharePoint)\r\n#   perf-buffer.json    15-minute performance summaries of the last 24 hours\r\n#   out\\                work folders and the deep inventory state of the scheduled runs\r\n#   queue\\              snapshots waiting for upload (oldest first, limited by age and count)\r\n#   logs\\               one log per day, kept 14 days\r\n\r\n$script:EP365QueueMaxAgeDays = 14\r\n$script:EP365QueueMaxCount = 30\r\n$script:EP365LogKeepDays = 14\r\n\r\nfunction Get-CollectorPaths {\r\n    param([string]$Root)\r\n    if ([string]::IsNullOrWhiteSpace($Root)) { $Root = Join-Path $env:ProgramData 'EP365Atlas' }\r\n    return @{\r\n        Root        = $Root\r\n        Config      = (Join-Path $Root 'collector.json')\r\n        Certificate = (Join-Path $Root 'certificate.json')\r\n        State       = (Join-Path $Root 'state.json')\r\n        Servers     = (Join-Path $Root 'farm-servers.json')\r\n        PerfBuffer  = (Join-Path $Root 'perf-buffer.json')\r\n        Out         = (Join-Path $Root 'out')\r\n        Queue       = (Join-Path $Root 'queue')\r\n        Logs        = (Join-Path $Root 'logs')\r\n        Script      = (Join-Path $Root 'Invoke-EP365AtlasCollector.ps1')\r\n    }\r\n}\r\n\r\nfunction Read-JsonFile {\r\n    # $null when the file does not exist; throws when it exists but is not JSON (never \"empty\").\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    if (-not (Test-Path -LiteralPath $Path)) { return $null }\r\n    $text = Read-Utf8File $Path\r\n    if ([string]::IsNullOrWhiteSpace($text)) { throw ('File is empty: ' + $Path) }\r\n    return (ConvertFrom-Json -InputObject $text)\r\n}\r\n\r\nfunction Write-JsonFile {\r\n    # Written to a temporary file first, then swapped in, so a reader never sees half a file.\r\n    param([Parameter(Mandatory = $true)][string]$Path, $Object)\r\n    $tmp = $Path + '.tmp'\r\n    Write-Utf8File -Path $tmp -Text (ConvertTo-Json -InputObject $Object -Depth 20 -Compress)\r\n    # NullString: a plain $null would reach File.Replace as '' (no backup file wanted).\r\n    if (Test-Path -LiteralPath $Path) { [System.IO.File]::Replace($tmp, $Path, [System.Management.Automation.Language.NullString]::Value) } else { [System.IO.File]::Move($tmp, $Path) }\r\n}\r\n\r\nfunction Initialize-TaskLog {\r\n    # Log of the scheduled run: logs\\collector-<yyyyMMdd>.log; logs older than 14 days are deleted.\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    if (-not (Test-Path -LiteralPath $Paths.Logs)) { [void](New-Item -ItemType Directory -Path $Paths.Logs -Force) }\r\n    $script:EP365TaskLogPath = Join-Path $Paths.Logs ('collector-' + [DateTime]::UtcNow.ToString('yyyyMMdd', $script:EP365Invariant) + '.log')\r\n    $limit = [DateTime]::UtcNow.AddDays(-$script:EP365LogKeepDays)\r\n    foreach ($f in @(Get-ChildItem -LiteralPath $Paths.Logs -File -Filter 'collector-*.log' -ErrorAction SilentlyContinue)) {\r\n        if ($f.LastWriteTimeUtc -lt $limit) { try { [System.IO.File]::Delete($f.FullName) } catch { } }\r\n    }\r\n}\r\n\r\nfunction Read-CollectorConfig {\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $cfg = $null\r\n    try { $cfg = Read-JsonFile $Paths.Config } catch { throw ('The configuration ' + $Paths.Config + ' is damaged: ' + (Format-ErrorText $_) + '. Run -Install again.') }\r\n    if ($null -eq $cfg) { throw ('The collector is not installed (' + $Paths.Config + ' is missing). Run -NewCertificate, Register-EP365AtlasCollectorApp.ps1 and -Install first.') }\r\n    foreach ($k in @('tenantId', 'clientId', 'driveId', 'inboxItemId', 'certificateThumbprint')) {\r\n        if ($null -eq (ConvertTo-NullableString (Get-Prop $cfg $k))) { throw ('The configuration has no ' + $k + '. Run -Install again.') }\r\n    }\r\n    return $cfg\r\n}\r\n\r\nfunction Read-CollectorState {\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $st = $null\r\n    try { $st = Read-JsonFile $Paths.State } catch { Write-CollectorLog -Level WARN -Message ('state.json is damaged and starts again: ' + (Format-ErrorText $_)) }\r\n    $out = [ordered]@{ spFarmId = $null; lastUploadAt = $null; lastUploadFile = $null; lastUploadFarmId = $null; lastErrorAt = $null; lastError = $null; lastRequestAt = $null }\r\n    if ($null -ne $st) { foreach ($k in @($out.Keys)) { $out[$k] = ConvertTo-NullableString (Get-Prop $st $k) } }\r\n    return $out\r\n}\r\n\r\nfunction Save-CollectorState {\r\n    param([Parameter(Mandatory = $true)]$Paths, [Parameter(Mandatory = $true)]$State)\r\n    Write-JsonFile -Path $Paths.State -Object $State\r\n}\r\n\r\nfunction Get-QueueFiles {\r\n    # Snapshots waiting for upload, oldest first. Only complete ZIPs (they are moved in when done).\r\n    param([Parameter(Mandatory = $true)][string]$QueueDir)\r\n    if (-not (Test-Path -LiteralPath $QueueDir)) { return }\r\n    @(Get-ChildItem -LiteralPath $QueueDir -File -Filter 'ep365-farm-*.zip' -ErrorAction Stop | Sort-Object -Property LastWriteTimeUtc, Name)\r\n}\r\n\r\nfunction Limit-CollectorQueue {\r\n    # Drops snapshots older than MaxAgeDays and, beyond MaxCount, the oldest ones (each logged).\r\n    # Returns the names that were dropped.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$QueueDir,\r\n        [datetime]$NowUtc = [DateTime]::UtcNow,\r\n        [int]$MaxAgeDays = $script:EP365QueueMaxAgeDays,\r\n        [int]$MaxCount = $script:EP365QueueMaxCount\r\n    )\r\n    $dropped = New-Object System.Collections.Generic.List[string]\r\n    $files = @(Get-QueueFiles $QueueDir)\r\n    $limit = $NowUtc.AddDays(-$MaxAgeDays)\r\n    $keep = New-Object System.Collections.Generic.List[object]\r\n    foreach ($f in $files) {\r\n        if ($f.LastWriteTimeUtc -lt $limit) { $dropped.Add($f.Name); [System.IO.File]::Delete($f.FullName) } else { $keep.Add($f) }\r\n    }\r\n    $over = $keep.Count - $MaxCount\r\n    for ($i = 0; $i -lt $over; $i++) { $dropped.Add($keep[$i].Name); [System.IO.File]::Delete($keep[$i].FullName) }\r\n    foreach ($n in $dropped) { Write-CollectorLog -Level WARN -Message ('queue: ' + $n + ' was not uploaded within the limits (' + $MaxAgeDays + ' days, ' + $MaxCount + ' snapshots) and was dropped') }\r\n    return , $dropped.ToArray()\r\n}\r\n\r\n$script:EP365MaxSnapshotBytes = 314572800\r\n$script:EP365SnapshotNameRx = '^ep365-farm-([0-9a-f]{8})-\\d{8}-\\d{4}(-\\d{1,3})?\\.zip$'\r\n\r\nfunction Get-SnapshotZipInfo {\r\n    # Checks that a file is a snapshot of this collector and returns its identity:\r\n    # name ep365-farm-<farm8>-<yyyyMMdd-HHmm>[-n].zip, readable ZIP, manifest.json of kind\r\n    # ep365.atlas.farm-snapshot with a farm id that matches the name. Throws with the reason.\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    $name = [System.IO.Path]::GetFileName($Path)\r\n    if ($name -notmatch $script:EP365SnapshotNameRx) { throw ('Not a snapshot of the collector (expected ep365-farm-<farm8>-<yyyyMMdd-HHmm>.zip): ' + $name) }\r\n    $prefix = $Matches[1].ToLowerInvariant()\r\n    $length = (New-Object System.IO.FileInfo $Path).Length\r\n    if ($length -gt $script:EP365MaxSnapshotBytes) { throw ($name + ' is larger than 300 MB; Atlas does not import such a snapshot.') }\r\n    Add-Type -AssemblyName System.IO.Compression\r\n    Add-Type -AssemblyName System.IO.Compression.FileSystem\r\n    $zip = $null\r\n    try { $zip = [System.IO.Compression.ZipFile]::OpenRead($Path) } catch { throw ('Not a readable ZIP file: ' + $name + ' (' + (Format-ErrorText $_) + ')') }\r\n    $text = $null\r\n    try {\r\n        $entry = @($zip.Entries | Where-Object { $_.Name -eq 'manifest.json' }) | Select-Object -First 1\r\n        if ($null -eq $entry) { throw ($name + ' has no manifest.json - it is not a snapshot of the collector.') }\r\n        $reader = New-Object System.IO.StreamReader ($entry.Open(), $script:EP365Utf8NoBom)\r\n        try { $text = $reader.ReadToEnd() } finally { $reader.Close() }\r\n    } finally {\r\n        $zip.Dispose()\r\n    }\r\n    $m = $null\r\n    try { $m = ConvertFrom-Json -InputObject $text } catch { throw ('manifest.json in ' + $name + ' is not JSON.') }\r\n    if ([string](Get-Prop $m 'kind') -ne $script:EP365SnapshotKind) { throw ('manifest.json in ' + $name + ' is not a farm snapshot manifest.') }\r\n    $farm = ConvertTo-NullableString (Get-Prop $m 'spFarmId')\r\n    if ($null -eq $farm -or $farm -notmatch '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { throw ('manifest.json in ' + $name + ' has no valid farm id.') }\r\n    $farm = $farm.ToLowerInvariant()\r\n    if (-not $farm.StartsWith($prefix)) { throw ('The name of ' + $name + ' does not match the farm id in its manifest (' + $farm + ').') }\r\n    return [pscustomobject]@{\r\n        Name        = $name\r\n        SpFarmId    = $farm\r\n        CollectedAt = (ConvertTo-IsoUtc (Get-Prop $m 'collectedAt') -AssumeUtc)\r\n        Mode        = (ConvertTo-NullableString (Get-Prop $m 'collector.mode'))\r\n        FarmName    = (ConvertTo-NullableString (Get-Prop $m 'farmName'))\r\n        Bytes       = $length\r\n    }\r\n}\r\n\r\nfunction Send-CollectorQueue {\r\n    # Uploads the queue oldest first, each snapshot into Inbox/<farm id of ITS manifest>. A file\r\n    # leaves the queue only after the library confirmed the full size. A transport or service\r\n    # failure stops the run (the next run tries again); a file that is not a readable snapshot is\r\n    # moved to queue\\rejected (logged, never deleted) and the run goes on.\r\n    # -SpFarmId = the farm of this server (scheduled runs): remembered in state.json for \"Collect now\".\r\n    param([Parameter(Mandatory = $true)]$Paths, [string]$SpFarmId)\r\n    $state = Read-CollectorState $Paths\r\n    $uploaded = New-Object System.Collections.Generic.List[string]\r\n    $rejected = New-Object System.Collections.Generic.List[string]\r\n    $errorText = $null\r\n    foreach ($f in @(Get-QueueFiles $Paths.Queue)) {\r\n        $info = $null\r\n        try { $info = Get-SnapshotZipInfo -Path $f.FullName }\r\n        catch {\r\n            $why = Format-ErrorText $_\r\n            $dir = Join-Path $Paths.Queue 'rejected'\r\n            if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }\r\n            $to = Join-Path $dir $f.Name\r\n            if (Test-Path -LiteralPath $to) { $to = Join-Path $dir ([DateTime]::UtcNow.ToString('yyyyMMddHHmmss', $script:EP365Invariant) + '-' + $f.Name) }\r\n            [System.IO.File]::Move($f.FullName, $to)\r\n            $rejected.Add($f.Name)\r\n            Write-CollectorLog -Level ERROR -Message ('queue: ' + $f.Name + ' is not a readable snapshot and was moved to ' + $to + ': ' + $why)\r\n            continue\r\n        }\r\n        if ($SpFarmId -and $info.SpFarmId -ne $SpFarmId.ToLowerInvariant()) {\r\n            Write-CollectorLog -Level WARN -Message ('queue: ' + $f.Name + ' belongs to farm ' + $info.SpFarmId + ', not to this farm; it goes into the Inbox folder of its own farm')\r\n        }\r\n        try {\r\n            [void](Send-InboxFile -Path $f.FullName -SpFarmId $info.SpFarmId)\r\n            [System.IO.File]::Delete($f.FullName)\r\n            $uploaded.Add($f.Name)\r\n            $state.lastUploadAt = Get-UtcNowIso\r\n            $state.lastUploadFile = $f.Name\r\n            $state.lastUploadFarmId = $info.SpFarmId\r\n            Write-CollectorLog -Message ('queue: ' + $f.Name + ' uploaded to Inbox/' + $info.SpFarmId)\r\n        } catch {\r\n            $errorText = Format-ErrorText $_\r\n            $state.lastErrorAt = Get-UtcNowIso\r\n            $state.lastError = $errorText\r\n            Write-CollectorLog -Level ERROR -Message ('queue: ' + $f.Name + ' not uploaded, stays in the queue: ' + $errorText)\r\n            break\r\n        }\r\n    }\r\n    if ($null -eq $errorText -and $uploaded.Count -gt 0) { $state.lastError = $null }\r\n    if ($SpFarmId) { $state.spFarmId = $SpFarmId.ToLowerInvariant() }\r\n    Save-CollectorState -Paths $Paths -State $state\r\n    return [pscustomobject]@{ Uploaded = $uploaded.ToArray(); Rejected = $rejected.ToArray(); Remaining = @(Get-QueueFiles $Paths.Queue).Count; Error = $errorText }\r\n}\r\n\r\nfunction Save-FarmServerCache {\r\n    # Servers of the farm for the 15-minute task (name, address, role).\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $list = @(Get-FarmServerList | ForEach-Object { [ordered]@{ Name = $_.Name; Address = $_.Address; Role = $_.Role } })\r\n    if ($list.Count -gt 0) { Write-JsonFile -Path $Paths.Servers -Object @{ savedAt = (Get-UtcNowIso); servers = $list } }\r\n}\r\n\r\nfunction Read-FarmServerCache {\r\n    # $true when the cache seeded the server list of this run.\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $c = $null\r\n    try { $c = Read-JsonFile $Paths.Servers } catch { return $false }\r\n    $servers = @(Get-PropList $c 'servers' | Where-Object { $null -ne $_ })\r\n    if ($servers.Count -eq 0) { return $false }\r\n    $script:EP365State.Cache['servers'] = @($servers | ForEach-Object { [pscustomobject]@{ Name = (Get-Prop $_ 'Name'); Address = (Get-Prop $_ 'Address'); Role = (Get-Prop $_ 'Role') } })\r\n    return $true\r\n}\r\n\r\n# ===================== 58-Install: certificate, configuration, scheduled tasks, uninstall =====================\r\n#\r\n# Changes only the collector's own things on THIS server: its folder, its certificate in\r\n# LocalMachine\\My (non-exportable key), read access of the task account to that key, and three\r\n# scheduled tasks in the folder \\EP365 Atlas\\. Never the farm, IIS or the SharePoint configuration.\r\n\r\n$script:EP365TaskPath = '\\EP365 Atlas\\'\r\n$script:EP365TaskDaily = 'EP365 Atlas - daily inventory'\r\n$script:EP365TaskDeep = 'EP365 Atlas - deep inventory'\r\n$script:EP365TaskPerf = 'EP365 Atlas - performance'\r\n$script:EP365GuidRx = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\r\n\r\nfunction Assert-RunAsAdministrator {\r\n    $p = New-Object System.Security.Principal.WindowsPrincipal ([System.Security.Principal.WindowsIdentity]::GetCurrent())\r\n    if (-not $p.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)) {\r\n        throw 'Run this step in an elevated Windows PowerShell 5.1 (Run as administrator).'\r\n    }\r\n}\r\n\r\nfunction Get-FarmLabel {\r\n    # Farm name for file and task names: letters, digits and '-' only.\r\n    param([string]$FarmName)\r\n    $s = ([string]$FarmName) -replace '[^A-Za-z0-9-]', ''\r\n    if ($s.Length -eq 0) { return 'farm' }\r\n    if ($s.Length -gt 24) { $s = $s.Substring(0, 24) }\r\n    return $s\r\n}\r\n\r\nfunction Test-TimeOfDay {\r\n    param([string]$Value)\r\n    if ($Value -notmatch '^(\\d{1,2}):(\\d{2})$') { return $false }\r\n    return ([int]$Matches[1] -le 23 -and [int]$Matches[2] -le 59)\r\n}\r\n\r\nfunction New-CollectorConfig {\r\n    # Validated configuration (no secrets). Throws on the first invalid value.\r\n    param(\r\n        [string]$TenantId, [string]$ClientId, [string]$SiteId, [string]$ListId, [string]$DriveId, [string]$InboxItemId, [string]$SiteUrl,\r\n        [string]$FarmName, [string]$CertificateThumbprint, [string]$TaskAccount, [string]$Proxy,\r\n        [string]$DailyAt = '05:00', [string]$DeepDay = 'Sunday', [string]$DeepAt = '02:00', [switch]$NoTasks\r\n    )\r\n    if ($TenantId -notmatch $script:EP365GuidRx) { throw ('-TenantId must be the tenant GUID (Register-EP365AtlasCollectorApp.ps1 prints it): ' + $TenantId) }\r\n    if ($ClientId -notmatch $script:EP365GuidRx) { throw ('-ClientId must be the application (client) GUID: ' + $ClientId) }\r\n    if ($ListId -notmatch $script:EP365GuidRx) { throw ('-ListId must be the GUID of the snapshot library: ' + $ListId) }\r\n    if ($SiteId -notmatch '^[A-Za-z0-9.-]+\\.sharepoint\\.com,[0-9a-fA-F-]{36},[0-9a-fA-F-]{36}$') { throw ('-SiteId must be the Graph site id (host,site GUID,web GUID): ' + $SiteId) }\r\n    if ($DriveId -notmatch '^b![A-Za-z0-9_-]+$') { throw ('-DriveId must be the Graph drive id of the snapshot library (starts with b!): ' + $DriveId) }\r\n    if ($InboxItemId -notmatch '^[A-Za-z0-9!_-]{8,}$') { throw ('-InboxItemId must be the Graph item id of the Inbox folder (Register-EP365AtlasCollectorApp.ps1 prints it): ' + $InboxItemId) }\r\n    if ($CertificateThumbprint -notmatch '^[0-9A-Fa-f]{40}$') { throw ('The certificate thumbprint is invalid: ' + $CertificateThumbprint) }\r\n    if ($TaskAccount -notmatch '^[^\\\\/\\s]+\\\\[^\\\\/]+$') {\r\n        if ($NoTasks) { throw ('The account that may use the certificate key must be DOMAIN\\name: ' + $TaskAccount) }\r\n        throw ('-TaskAccount must be DOMAIN\\name (a gMSA ends with $): ' + $TaskAccount)\r\n    }\r\n    if (-not (Test-TimeOfDay $DailyAt)) { throw ('-DailyAt must be HH:mm: ' + $DailyAt) }\r\n    if (-not (Test-TimeOfDay $DeepAt)) { throw ('-DeepAt must be HH:mm: ' + $DeepAt) }\r\n    if ($Proxy -and $Proxy -notmatch '^https?://[^\\s]+$') { throw ('-Proxy must be an http(s) URL: ' + $Proxy) }\r\n    if ($SiteUrl -and $SiteUrl -notmatch '^https://[^\\s]+$') { throw ('-SiteUrl must be an https URL: ' + $SiteUrl) }\r\n    return [ordered]@{\r\n        version               = 1\r\n        tenantId              = $TenantId.ToLowerInvariant()\r\n        clientId              = $ClientId.ToLowerInvariant()\r\n        siteId                = $SiteId\r\n        listId                = $ListId.ToLowerInvariant()\r\n        driveId               = $DriveId\r\n        inboxItemId           = $InboxItemId\r\n        siteUrl               = (ConvertTo-NullableString $SiteUrl)\r\n        farmName              = (ConvertTo-NullableString $FarmName)\r\n        certificateThumbprint = $CertificateThumbprint.ToUpperInvariant()\r\n        taskAccount           = $TaskAccount\r\n        tasks                 = (-not $NoTasks)\r\n        proxy                 = (ConvertTo-NullableString $Proxy)\r\n        schedule              = [ordered]@{ dailyAt = $DailyAt; deepDay = $DeepDay; deepAt = $DeepAt; perfEveryMinutes = $script:EP365PerfWindowMinutes }\r\n        installedAt           = (Get-UtcNowIso)\r\n        collectorVersion      = $script:EP365CollectorVersion\r\n    }\r\n}\r\n\r\nfunction Resolve-InstallAccount {\r\n    # Account that gets read access to the certificate key: the task account, or with -NoTasks the\r\n    # current user (the one who will run -SendFile and -TestConnection on this computer).\r\n    param([string]$TaskAccount, [switch]$NoTasks)\r\n    if ($TaskAccount) { return $TaskAccount }\r\n    if ($NoTasks) { return [System.Security.Principal.WindowsIdentity]::GetCurrent().Name }\r\n    throw '-TaskAccount is required (the account of the scheduled tasks). Use -NoTasks for a computer that only sends snapshots with -SendFile.'\r\n}\r\n\r\nfunction Get-CollectorTaskSpecs {\r\n    # The three scheduled tasks (pure data, so the tests can check them without registering anything).\r\n    param([Parameter(Mandatory = $true)][string]$ScriptPath, [string]$DailyAt = '05:00', [string]$DeepDay = 'Sunday', [string]$DeepAt = '02:00')\r\n    $base = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"' + $ScriptPath + '\"'\r\n    return @(\r\n        [pscustomobject]@{ Name = $script:EP365TaskDaily; Arguments = ($base + ' -Upload'); Kind = 'Daily'; At = $DailyAt; Day = $null; EveryMinutes = $null; LimitMinutes = 240 },\r\n        [pscustomobject]@{ Name = $script:EP365TaskDeep; Arguments = ($base + ' -Upload -Deep'); Kind = 'Weekly'; At = $DeepAt; Day = $DeepDay; EveryMinutes = $null; LimitMinutes = 480 },\r\n        [pscustomobject]@{ Name = $script:EP365TaskPerf; Arguments = ($base + ' -PerfTick'); Kind = 'Repeat'; At = $null; Day = $null; EveryMinutes = $script:EP365PerfWindowMinutes; LimitMinutes = 20 }\r\n    )\r\n}\r\n\r\nfunction Find-CollectorCertificate {\r\n    # Certificate with the private key in LocalMachine\\My by thumbprint; $null when missing.\r\n    param([Parameter(Mandatory = $true)][string]$Thumbprint)\r\n    $store = New-Object System.Security.Cryptography.X509Certificates.X509Store ('My', 'LocalMachine')\r\n    $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly)\r\n    try {\r\n        foreach ($c in $store.Certificates) {\r\n            if ($c.Thumbprint -ieq $Thumbprint) { return $c }\r\n        }\r\n    } finally {\r\n        $store.Close()\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Get-CertificateKeyFile {\r\n    # File of the machine key behind the certificate (CNG: Crypto\\Keys, legacy CSP: Crypto\\RSA\\MachineKeys).\r\n    param([Parameter(Mandatory = $true)]$Certificate)\r\n    $rsa = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($Certificate)\r\n    if ($null -eq $rsa) { return $null }\r\n    $name = $null; $dir = $null\r\n    if ($rsa -is [System.Security.Cryptography.RSACng]) { $name = $rsa.Key.UniqueName; $dir = Join-Path $env:ProgramData 'Microsoft\\Crypto\\Keys' }\r\n    elseif ($rsa -is [System.Security.Cryptography.RSACryptoServiceProvider]) { $name = $rsa.CspKeyContainerInfo.UniqueKeyContainerName; $dir = Join-Path $env:ProgramData 'Microsoft\\Crypto\\RSA\\MachineKeys' }\r\n    if (-not $name) { return $null }\r\n    $path = Join-Path $dir $name\r\n    if (Test-Path -LiteralPath $path) { return $path }\r\n    return $null\r\n}\r\n\r\nfunction Grant-CertificateKeyRead {\r\n    param([Parameter(Mandatory = $true)]$Certificate, [Parameter(Mandatory = $true)][string]$Account)\r\n    $file = Get-CertificateKeyFile $Certificate\r\n    if ($null -eq $file) { throw 'The private key file of the certificate was not found; access for the task account cannot be granted.' }\r\n    $acl = Get-Acl -LiteralPath $file\r\n    $rule = New-Object System.Security.AccessControl.FileSystemAccessRule ($Account, [System.Security.AccessControl.FileSystemRights]::Read, [System.Security.AccessControl.AccessControlType]::Allow)\r\n    $acl.AddAccessRule($rule)\r\n    Set-Acl -LiteralPath $file -AclObject $acl\r\n}\r\n\r\nfunction Initialize-CollectorFolder {\r\n    # Creates the folder tree and limits it to SYSTEM and Administrators (full) and the task account\r\n    # (modify): the tasks run the script copy in this folder under the task account.\r\n    param([Parameter(Mandatory = $true)]$Paths, [string]$TaskAccount)\r\n    foreach ($d in @($Paths.Root, $Paths.Queue, $Paths.Out, $Paths.Logs)) {\r\n        if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) }\r\n    }\r\n    $inherit = [System.Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit'\r\n    $none = [System.Security.AccessControl.PropagationFlags]::None\r\n    $allow = [System.Security.AccessControl.AccessControlType]::Allow\r\n    $sec = New-Object System.Security.AccessControl.DirectorySecurity\r\n    $sec.SetAccessRuleProtection($true, $false)\r\n    $system = New-Object System.Security.Principal.SecurityIdentifier ('S-1-5-18')\r\n    $admins = New-Object System.Security.Principal.SecurityIdentifier ('S-1-5-32-544')\r\n    $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($system, 'FullControl', $inherit, $none, $allow)))\r\n    $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($admins, 'FullControl', $inherit, $none, $allow)))\r\n    if ($TaskAccount) { $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($TaskAccount, 'Modify', $inherit, $none, $allow))) }\r\n    Set-Acl -LiteralPath $Paths.Root -AclObject $sec\r\n}\r\n\r\nfunction New-EP365CollectorCertificate {\r\n    # Step 1 on the farm: certificate for the collector application (reused while valid > 30 days).\r\n    param([string]$FarmName, [string]$Root)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-CollectorFolder -Paths $paths\r\n    $label = Get-FarmLabel $FarmName\r\n    $cerPath = Join-Path $paths.Root ('ep365-atlas-collector-' + $label + '.cer')\r\n    $info = $null\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n    $cert = $null\r\n    $old = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n    if ($old) {\r\n        $c = Find-CollectorCertificate $old\r\n        if ($null -ne $c -and $c.HasPrivateKey -and $c.NotAfter.ToUniversalTime() -gt [DateTime]::UtcNow.AddDays(30)) { $cert = $c }\r\n    }\r\n    $created = $false\r\n    if ($null -eq $cert) {\r\n        $cert = New-SelfSignedCertificate -Subject ('CN=EP365 Atlas collector ' + $label + ' ' + $env:COMPUTERNAME) -FriendlyName ('EP365 Atlas collector ' + $label) `\r\n            -CertStoreLocation 'Cert:\\LocalMachine\\My' -Provider 'Microsoft Software Key Storage Provider' -KeyAlgorithm RSA -KeyLength 2048 `\r\n            -HashAlgorithm SHA256 -KeyExportPolicy NonExportable -KeyUsage DigitalSignature -Type Custom -NotAfter ([DateTime]::Now.AddYears(2))\r\n        $created = $true\r\n    }\r\n    [System.IO.File]::WriteAllBytes($cerPath, $cert.RawData)\r\n    Write-JsonFile -Path $paths.Certificate -Object ([ordered]@{ thumbprint = $cert.Thumbprint; subject = $cert.Subject; notAfter = (ConvertTo-IsoUtc $cert.NotAfter); cerFile = $cerPath; farmName = (ConvertTo-NullableString $FarmName) })\r\n    Write-Host ''\r\n    if ($created) { Write-Host 'Certificate created in LocalMachine\\My (private key cannot be exported).' -ForegroundColor Green }\r\n    else { Write-Host 'A valid certificate from an earlier run is reused.' -ForegroundColor Green }\r\n    Write-Host ('  Thumbprint: ' + $cert.Thumbprint)\r\n    Write-Host ('  Valid until: ' + $cert.NotAfter.ToString('yyyy-MM-dd'))\r\n    Write-Host ('  Public part: ' + $cerPath)\r\n    Write-Host ''\r\n    Write-Host 'Next: give the .cer file (public part only, no secret) to the tenant administrator for Register-EP365AtlasCollectorApp.ps1.'\r\n    return $cert\r\n}\r\n\r\nfunction Register-CollectorTasks {\r\n    param([Parameter(Mandatory = $true)]$Specs, [Parameter(Mandatory = $true)][string]$TaskAccount, $Credential, [string]$WorkingDirectory)\r\n    $gmsa = $TaskAccount.EndsWith('$')\r\n    foreach ($spec in $Specs) {\r\n        $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $spec.Arguments -WorkingDirectory $WorkingDirectory\r\n        if ($spec.Kind -eq 'Daily') { $trigger = New-ScheduledTaskTrigger -Daily -At $spec.At }\r\n        elseif ($spec.Kind -eq 'Weekly') { $trigger = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $spec.Day -At $spec.At }\r\n        else {\r\n            $first = [DateTime]::Now.Date.AddMinutes(([math]::Floor([DateTime]::Now.TimeOfDay.TotalMinutes / $spec.EveryMinutes) + 1) * $spec.EveryMinutes)\r\n            $trigger = New-ScheduledTaskTrigger -Once -At $first -RepetitionInterval (New-TimeSpan -Minutes $spec.EveryMinutes)\r\n        }\r\n        $settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes $spec.LimitMinutes) -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries\r\n        if ($gmsa) {\r\n            $principal = New-ScheduledTaskPrincipal -UserId $TaskAccount -LogonType Password -RunLevel Highest\r\n            [void](Register-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $spec.Name -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force)\r\n        } else {\r\n            [void](Register-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $spec.Name -Action $action -Trigger $trigger -Settings $settings -User $Credential.UserName -Password $Credential.GetNetworkCredential().Password -RunLevel Highest -Force)\r\n        }\r\n        Write-Host ('  Task ' + $script:EP365TaskPath + $spec.Name + ' registered')\r\n    }\r\n}\r\n\r\nfunction Install-EP365Collector {\r\n    # Step 3 on the farm.\r\n    param(\r\n        [string]$TenantId, [string]$ClientId, [string]$SiteId, [string]$ListId, [string]$DriveId, [string]$InboxItemId, [string]$SiteUrl, [string]$FarmName,\r\n        [string]$TaskAccount, [string]$CertificateThumbprint, [string]$DailyAt, [string]$DeepDay, [string]$DeepAt, [string]$Proxy,\r\n        [switch]$StartNow, [switch]$NoTasks, [string]$Root\r\n    )\r\n    Assert-RunAsAdministrator\r\n    $TaskAccount = Resolve-InstallAccount -TaskAccount $TaskAccount -NoTasks:$NoTasks\r\n    $paths = Get-CollectorPaths $Root\r\n    if (-not $CertificateThumbprint) {\r\n        $info = $null\r\n        try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n        $CertificateThumbprint = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n        if (-not $CertificateThumbprint) { throw 'No certificate yet: run -NewCertificate first (or pass -CertificateThumbprint).' }\r\n    }\r\n    if (-not $FarmName) {\r\n        try { $FarmName = ConvertTo-NullableString (Get-Prop (Read-JsonFile $paths.Certificate) 'farmName') } catch { }\r\n    }\r\n    $cfg = New-CollectorConfig -TenantId $TenantId -ClientId $ClientId -SiteId $SiteId -ListId $ListId -DriveId $DriveId -InboxItemId $InboxItemId -SiteUrl $SiteUrl -FarmName $FarmName `\r\n        -CertificateThumbprint $CertificateThumbprint -TaskAccount $TaskAccount -Proxy $Proxy -DailyAt $DailyAt -DeepDay $DeepDay -DeepAt $DeepAt -NoTasks:$NoTasks\r\n    $cert = Find-CollectorCertificate $cfg.certificateThumbprint\r\n    if ($null -eq $cert -or -not $cert.HasPrivateKey) { throw ('Certificate ' + $cfg.certificateThumbprint + ' with its private key is not in LocalMachine\\My on this server.') }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow.AddDays(1)) { throw 'The certificate has expired. Run -NewCertificate and register the new .cer file.' }\r\n\r\n    $credential = $null\r\n    if (-not $NoTasks -and -not $TaskAccount.EndsWith('$')) {\r\n        $credential = Get-Credential -UserName $TaskAccount -Message 'Password of the account that runs the EP365 Atlas tasks. Windows Task Scheduler stores it; the collector does not.'\r\n        if ($null -eq $credential) { throw 'No password entered; nothing was installed.' }\r\n    }\r\n    if ($NoTasks) { Write-Host 'Installing the EP365 Atlas collector without scheduled tasks (sending with -SendFile only)' -ForegroundColor Cyan }\r\n    else { Write-Host 'Installing the EP365 Atlas collector (automatic mode)' -ForegroundColor Cyan }\r\n    Initialize-CollectorFolder -Paths $paths -TaskAccount $TaskAccount\r\n    Write-Host ('  Folder ' + $paths.Root + ' (SYSTEM, Administrators, ' + $TaskAccount + ')')\r\n    if ($script:EP365ScriptPath -and $script:EP365ScriptPath -ine $paths.Script) { [System.IO.File]::Copy($script:EP365ScriptPath, $paths.Script, $true) }\r\n    Write-Host ('  Script ' + $paths.Script)\r\n    Write-JsonFile -Path $paths.Config -Object $cfg\r\n    Write-Host ('  Configuration ' + $paths.Config)\r\n    Grant-CertificateKeyRead -Certificate $cert -Account $TaskAccount\r\n    Write-Host ('  ' + $TaskAccount + ' may use the private key of certificate ' + $cert.Thumbprint)\r\n    if (-not $NoTasks) {\r\n        Register-CollectorTasks -Specs (Get-CollectorTaskSpecs -ScriptPath $paths.Script -DailyAt $cfg.schedule.dailyAt -DeepDay $cfg.schedule.deepDay -DeepAt $cfg.schedule.deepAt) `\r\n            -TaskAccount $TaskAccount -Credential $credential -WorkingDirectory $paths.Root\r\n    } else {\r\n        Write-Host '  No scheduled tasks (-NoTasks)'\r\n    }\r\n\r\n    Initialize-GraphSession -Config ([pscustomobject]$cfg) -Certificate $cert\r\n    try {\r\n        Write-Host ('  Connection: ' + (Test-InboxAccess)) -ForegroundColor Green\r\n    } catch {\r\n        Write-Host ('  Connection test failed: ' + (Format-ErrorText $_)) -ForegroundColor Yellow\r\n        Write-Host '  Check the registration, then run -TestConnection.' -ForegroundColor Yellow\r\n    }\r\n    if ($NoTasks) {\r\n        if ($StartNow) { Write-Host '  -StartNow is ignored: there are no scheduled tasks.' -ForegroundColor Yellow }\r\n        Write-Host ''\r\n        Write-Host 'Next: -TestConnection (sign-in, Inbox and the check that the application sees nothing else), then -SendFile <snapshot ZIP>.'\r\n        return\r\n    }\r\n    if ($StartNow) {\r\n        Start-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365TaskDaily\r\n        Write-Host '  The first inventory is running now.'\r\n    }\r\n    Write-Host ''\r\n    Write-Host ('Daily inventory at {0}, deep inventory on {1} at {2}, performance every {3} minutes.' -f $cfg.schedule.dailyAt, $cfg.schedule.deepDay, $cfg.schedule.deepAt, $script:EP365PerfWindowMinutes)\r\n    Write-Host 'Snapshots wait in the Inbox of the snapshot library until an Atlas administrator opens Atlas.'\r\n}\r\n\r\nfunction Uninstall-EP365Collector {\r\n    param([string]$Root, [switch]$KeepCertificate)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    foreach ($n in @($script:EP365TaskDaily, $script:EP365TaskDeep, $script:EP365TaskPerf)) {\r\n        $t = Get-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $n -ErrorAction SilentlyContinue\r\n        if ($null -ne $t) { Unregister-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $n -Confirm:$false; Write-Host ('  Task ' + $n + ' removed') }\r\n    }\r\n    $cfg = $null; $info = $null\r\n    try { $cfg = Read-JsonFile $paths.Config } catch { }\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { }\r\n    $thumb = ConvertTo-NullableString (Get-Prop $cfg 'certificateThumbprint')\r\n    if (-not $thumb) { $thumb = ConvertTo-NullableString (Get-Prop $info 'thumbprint') }\r\n    $queued = @(Get-QueueFiles $paths.Queue).Count\r\n    if ($queued -gt 0) { Write-Host ('  {0} snapshot(s) in the queue were never uploaded and are deleted with the folder.' -f $queued) -ForegroundColor Yellow }\r\n    if ($thumb -and -not $KeepCertificate) {\r\n        $cert = Find-CollectorCertificate $thumb\r\n        if ($null -ne $cert) {\r\n            $keyFile = Get-CertificateKeyFile $cert\r\n            $store = New-Object System.Security.Cryptography.X509Certificates.X509Store ('My', 'LocalMachine')\r\n            $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite)\r\n            try { $store.Remove($cert) } finally { $store.Close() }\r\n            if ($keyFile -and (Test-Path -LiteralPath $keyFile)) { [System.IO.File]::Delete($keyFile) }\r\n            Write-Host ('  Certificate ' + $thumb + ' and its key removed')\r\n        }\r\n    }\r\n    if ((Test-Path -LiteralPath $paths.Root) -and ($paths.Root.TrimEnd('\\') -like '*\\EP365Atlas')) {\r\n        [System.IO.Directory]::Delete($paths.Root, $true)\r\n        Write-Host ('  Folder ' + $paths.Root + ' removed')\r\n    }\r\n    $client = ConvertTo-NullableString (Get-Prop $cfg 'clientId')\r\n    Write-Host ''\r\n    Write-Host 'The collector is removed from this server.' -ForegroundColor Green\r\n    if ($client) { Write-Host ('Ask the tenant administrator to delete the Entra application ' + $client + ' (App registrations); that also ends its access to the snapshot library.') }\r\n}\r\n\r\n# ===================== access 10: version, configuration from Atlas, folder, guarded reads =====================\r\n#\r\n# Shared with the farm collector (concatenated before this file): 10-Core (log, value helpers,\r\n# module runner), 55-Graph (certificate sign-in, Inbox upload), 56-Queue (JSON files, queue limits),\r\n# 58-Install (certificate key access, folder ACL, scheduled tasks). Functions defined again below\r\n# replace the farm variants for this script.\r\n\r\n$script:EP365AccessCollectorVersion = '1.0.0'\r\n$script:EP365CollectorVersion = $script:EP365AccessCollectorVersion\r\n$script:EP365SnapshotKind = 'ep365.atlas.access-snapshot'\r\n$script:EP365AccessModules = @('access', 'sitesSelected')\r\n$script:EP365AccessTask = 'EP365 Atlas - access snapshots'\r\n$script:EP365AccessZipRx = '^ep365-access-\\d{8}-\\d{4}(-\\d{1,3})?\\.zip$'\r\n# Mirrors Atlas: snapshot cap of places (root + places below it) and the items cap per list.\r\n$script:EP365AccessMaxSecurables = 1000\r\n$script:EP365AccessMaxItemsPerList = 20000\r\n$script:EP365AccessMaxGraphPages = 20\r\n\r\n# Configuration written by Atlas when the script is downloaded (JSON, ASCII, no secret):\r\n# tenantId, tenantUrl, atlasUrl, places, sitesSelected, includeLists, preparedAt.\r\n$script:EP365AccessPresetJson = '__EP365_ACCESS_PRESET__'\r\n\r\n# Raw response bodies of the module being collected; see New-RawResponse and Save-ModuleFile.\r\n$script:EP365AccessRaw = New-Object System.Collections.Generic.List[string]\r\n\r\nfunction Get-AccessPreset {\r\n    $text = [string]$script:EP365AccessPresetJson\r\n    if ($text -eq ('__EP365_ACCESS' + '_PRESET__') -or [string]::IsNullOrWhiteSpace($text)) {\r\n        throw 'This copy of the script carries no configuration. Download the collector from Atlas (Access > Snapshots and differences > Scheduled collection).'\r\n    }\r\n    $p = $null\r\n    try { $p = ConvertFrom-Json -InputObject $text } catch { throw ('The configuration inside the script is damaged: ' + (Format-ErrorText $_)) }\r\n    $tenant = ConvertTo-NullableString (Get-Prop $p 'tenantId')\r\n    $url = ConvertTo-NullableString (Get-Prop $p 'tenantUrl')\r\n    if ($null -eq $tenant -or $tenant -notmatch '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { throw 'The configuration inside the script has no valid tenant id.' }\r\n    if ($null -eq $url -or $url -notmatch '^https://[A-Za-z0-9-]+\\.sharepoint\\.com$') { throw 'The configuration inside the script has no valid tenant address.' }\r\n    return $p\r\n}\r\n\r\nfunction Get-AccessPlaces {\r\n    param($Preset)\r\n    return @(Get-PropList $Preset 'places' | Where-Object { $null -ne $_ })\r\n}\r\n\r\n# ---------- folder (replaces the farm variant) ----------\r\n\r\nfunction Get-CollectorPaths {\r\n    param([string]$Root)\r\n    if ([string]::IsNullOrWhiteSpace($Root)) { $Root = Join-Path $env:ProgramData 'EP365AtlasAccess' }\r\n    return @{\r\n        Root        = $Root\r\n        Config      = (Join-Path $Root 'collector.json')\r\n        Certificate = (Join-Path $Root 'certificate.json')\r\n        State       = (Join-Path $Root 'state.json')\r\n        Out         = (Join-Path $Root 'out')\r\n        Queue       = (Join-Path $Root 'queue')\r\n        Logs        = (Join-Path $Root 'logs')\r\n        Script      = (Join-Path $Root 'Invoke-EP365AtlasAccessCollector.ps1')\r\n    }\r\n}\r\n\r\nfunction Get-QueueFiles {\r\n    # Snapshots waiting for upload, oldest first (replaces the farm variant; used by Limit-CollectorQueue).\r\n    param([Parameter(Mandatory = $true)][string]$QueueDir)\r\n    if (-not (Test-Path -LiteralPath $QueueDir)) { return }\r\n    @(Get-ChildItem -LiteralPath $QueueDir -File -Filter 'ep365-access-*.zip' -ErrorAction Stop | Sort-Object -Property LastWriteTimeUtc, Name)\r\n}\r\n\r\nfunction Get-ModuleFunctionName {\r\n    param([string]$Id)\r\n    $map = @{ access = 'Get-AccessModuleData'; sitesSelected = 'Get-SitesSelectedModuleData' }\r\n    return $map[$Id]\r\n}\r\n\r\n# ---------- module files with raw response bodies ----------\r\n\r\nfunction Get-JsonValue {\r\n    # Property whose name contains a dot ('odata.nextLink', '@odata.nextLink'); $null when missing.\r\n    param($Object, [Parameter(Mandatory = $true)][string]$Name)\r\n    if ($null -eq $Object) { return $null }\r\n    $p = $Object.PSObject.Properties[$Name]\r\n    if ($null -eq $p) { return $null }\r\n    return , $p.Value\r\n}\r\n\r\nfunction New-RawResponse {\r\n    # { status, body } for the module file. The body is kept as the exact JSON text SharePoint or\r\n    # Graph returned (no round trip through PowerShell objects); a placeholder stands in until\r\n    # Save-ModuleFile writes the file. A body that is not valid JSON is stored as null.\r\n    param([Parameter(Mandatory = $true)]$Response)\r\n    $body = $null\r\n    if ($null -ne $Response.Json -and $Response.Text) {\r\n        $script:EP365AccessRaw.Add($Response.Text)\r\n        $body = '@@EP365RAW:' + ($script:EP365AccessRaw.Count - 1) + '@@'\r\n    }\r\n    return [ordered]@{ status = [int]$Response.Status; body = $body }\r\n}\r\n\r\nfunction Expand-RawBodies {\r\n    param([Parameter(Mandatory = $true)][string]$Json)\r\n    if ($script:EP365AccessRaw.Count -eq 0) { return $Json }\r\n    $rx = New-Object System.Text.RegularExpressions.Regex ('\"@@EP365RAW:(\\d+)@@\"')\r\n    $sb = New-Object System.Text.StringBuilder ($Json.Length + 1024)\r\n    $pos = 0\r\n    foreach ($m in $rx.Matches($Json)) {\r\n        [void]$sb.Append($Json, $pos, $m.Index - $pos)\r\n        [void]$sb.Append($script:EP365AccessRaw[[int]$m.Groups[1].Value])\r\n        $pos = $m.Index + $m.Length\r\n    }\r\n    [void]$sb.Append($Json, $pos, $Json.Length - $pos)\r\n    return $sb.ToString()\r\n}\r\n\r\nfunction Save-ModuleFile {\r\n    # Replaces the farm variant: same wrapper { schemaVersion, module, collectedAt, errors, data },\r\n    # raw bodies expanded, no anonymization.\r\n    param([Parameter(Mandatory = $true)]$Ctx, $Data, [Parameter(Mandatory = $true)][string]$FileName)\r\n    $wrapper = [ordered]@{\r\n        schemaVersion = $script:EP365SchemaVersion\r\n        module        = $Ctx.Id\r\n        collectedAt   = $Ctx.CollectedAt\r\n        errors        = @($Ctx.Errors.ToArray())\r\n        data          = $Data\r\n    }\r\n    $json = Expand-RawBodies (ConvertTo-SnapshotJson $wrapper)\r\n    Write-Utf8File -Path (Join-Path $script:EP365State.WorkDir $FileName) -Text $json\r\n    $script:EP365AccessRaw.Clear()\r\n}\r\n\r\n# ---------- sign-in for SharePoint and guarded reads ----------\r\n\r\nfunction Get-AccessTenantHost {\r\n    $p = $script:EP365State.Preset\r\n    return ([Uri]([string](Get-Prop $p 'tenantUrl'))).Host.ToLowerInvariant()\r\n}\r\n\r\nfunction Test-AccessReadTarget {\r\n    # $true for the reads the collector may send: SharePoint REST (/_api/) on the tenant host or\r\n    # its OneDrive host, Microsoft Graph /v1.0/sites and /v1.0/groups. GET only.\r\n    param([string]$Uri)\r\n    $u = $null\r\n    if (-not [Uri]::TryCreate($Uri, [UriKind]::Absolute, [ref]$u)) { return $false }\r\n    if ($u.Scheme -ne 'https') { return $false }\r\n    $h = $u.Host.ToLowerInvariant()\r\n    $tenantHost = Get-AccessTenantHost\r\n    $myHost = $tenantHost -replace '^([a-z0-9-]+)\\.sharepoint\\.com$', '$1-my.sharepoint.com'\r\n    if ($h -eq $tenantHost -or $h -eq $myHost) { return ($u.AbsolutePath -match '(?i)/_api/') }\r\n    if ($h -eq $script:EP365GraphHost) { return ($u.AbsolutePath -match '^/v1\\.0/(sites|groups)(/|$)') }\r\n    return $false\r\n}\r\n\r\nfunction Get-ResourceToken {\r\n    # App-only token for SharePoint (https://<host>/.default) or Microsoft Graph; cached per resource.\r\n    param([Parameter(Mandatory = $true)][string]$Resource)\r\n    if ($Resource -eq ('https://' + $script:EP365GraphHost)) { return (Get-GraphAccessToken) }\r\n    $g = $script:EP365Graph\r\n    if ($null -eq $g) { throw 'The sign-in session is not initialized' }\r\n    if ($null -eq $g.ResourceTokens) { $g.ResourceTokens = @{} }\r\n    $c = $g.ResourceTokens[$Resource]\r\n    if ($null -ne $c -and [DateTime]::UtcNow -lt $c.ExpiresUtc) { return $c.Token }\r\n    $tenant = [string](Get-Prop $g.Config 'tenantId')\r\n    $client = [string](Get-Prop $g.Config 'clientId')\r\n    $jwt = New-ClientAssertion -Certificate $g.Certificate -TenantId $tenant -ClientId $client\r\n    $form = 'client_id=' + [Uri]::EscapeDataString($client) +\r\n        '&scope=' + [Uri]::EscapeDataString($Resource + '/.default') +\r\n        '&client_assertion_type=' + [Uri]::EscapeDataString('urn:ietf:params:oauth:client-assertion-type:jwt-bearer') +\r\n        '&client_assertion=' + [Uri]::EscapeDataString($jwt) +\r\n        '&grant_type=client_credentials'\r\n    $r = Invoke-GraphRequest -Method POST -Uri (Get-TokenUrl $tenant) -Body ([Text.Encoding]::ASCII.GetBytes($form)) -ContentType 'application/x-www-form-urlencoded' -NoAuth\r\n    if ($r.Status -ne 200) { throw ('Sign-in of the collector application to ' + $Resource + ' failed: ' + (Get-GraphErrorText $r)) }\r\n    $j = ConvertFrom-Json -InputObject $r.Text\r\n    $token = ConvertTo-NullableString (Get-Prop $j 'access_token')\r\n    if ($null -eq $token) { throw ('Sign-in to ' + $Resource + ' returned no access token') }\r\n    $life = ConvertTo-NullableInt (Get-Prop $j 'expires_in')\r\n    if ($null -eq $life -or $life -lt 600) { $life = 600 }\r\n    $g.ResourceTokens[$Resource] = @{ Token = $token; ExpiresUtc = [DateTime]::UtcNow.AddSeconds($life - 300) }\r\n    return $token\r\n}\r\n\r\nfunction Invoke-AccessGet {\r\n    # Guarded GET with retries (429 and 5xx: Retry-After or 2, 4, 8 ... s; 401 renews the token once).\r\n    # Returns @{ Status; Text; Json } - Json = parsed body or $null. Throws only when the request is\r\n    # not allowed or the network never answered.\r\n    param([Parameter(Mandatory = $true)][string]$Uri, [int]$MaxAttempts = $script:EP365HttpMaxAttempts)\r\n    if (-not (Test-AccessReadTarget $Uri)) { throw ('Blocked: the collector may not read ' + ($Uri -replace '\\?.*$', '')) }\r\n    $u = [Uri]$Uri\r\n    $resource = 'https://' + $u.Host.ToLowerInvariant()\r\n    $accept = 'application/json'\r\n    if ($u.Host -ine $script:EP365GraphHost) { $accept = 'application/json;odata=nometadata' }\r\n    $renewed = $false\r\n    for ($attempt = 1; ; $attempt++) {\r\n        $h = @{ Authorization = ('Bearer ' + (Get-ResourceToken $resource)) }\r\n        $resp = $null\r\n        $transport = $null\r\n        try { $resp = Invoke-HttpRaw -Method GET -Uri $Uri -Headers $h -Accept $accept }\r\n        catch { $transport = Format-ErrorText $_ }\r\n        $wait = 0\r\n        $retry = $false\r\n        if ($null -ne $transport) { $retry = $true }\r\n        elseif ($resp.Status -eq 429 -or $resp.Status -ge 500) { $retry = $true; $wait = Get-RetryAfterSeconds $resp }\r\n        elseif ($resp.Status -eq 401 -and -not $renewed) {\r\n            $retry = $true; $renewed = $true\r\n            if ($resource -eq ('https://' + $script:EP365GraphHost)) { $script:EP365Graph.Token = $null } else { $script:EP365Graph.ResourceTokens.Remove($resource) }\r\n        }\r\n        if (-not $retry -or $attempt -ge $MaxAttempts) {\r\n            if ($null -ne $transport) { throw ('Network error (GET {0}): {1}' -f ($Uri -replace '\\?.*$', ''), $transport) }\r\n            $text = [string]$resp.Text\r\n            if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }\r\n            $json = $null\r\n            $t = $text.Trim()\r\n            if ($t.StartsWith('{') -or $t.StartsWith('[')) { try { $json = ConvertFrom-Json -InputObject $t } catch { $json = $null } }\r\n            return @{ Status = [int]$resp.Status; Text = $t; Json = $json }\r\n        }\r\n        if ($wait -le 0 -and ($null -eq $resp -or $resp.Status -ne 401)) { $wait = [int][math]::Pow(2, $attempt) }\r\n        if ($wait -gt 300) { $wait = 300 }\r\n        $why = $transport\r\n        if ($null -eq $why) { $why = 'HTTP ' + $resp.Status }\r\n        Write-CollectorLog -Level WARN -Message ('GET {0}: {1}, attempt {2} of {3}, next in {4} s' -f ($Uri -replace '\\?.*$', ''), $why, $attempt, $MaxAttempts, $wait)\r\n        if ($wait -gt 0) { Start-CollectorSleep -Seconds $wait }\r\n    }\r\n}\r\n\r\nfunction Test-Ok { param($Response) return ($null -ne $Response -and $Response.Status -ge 200 -and $Response.Status -lt 300 -and $null -ne $Response.Json) }\r\n\r\nfunction Get-ValueList {\r\n    # Items of 'value' in a parsed OData / Graph answer (never $null).\r\n    param($Json)\r\n    if ($null -eq $Json) { return @() }\r\n    $v = Get-JsonValue $Json 'value'\r\n    if ($null -eq $v) { return @() }\r\n    return @($v)\r\n}\r\n\r\n# ===================== access 20: module 'access' - raw permission data of the chosen places =====================\r\n#\r\n# Reads exactly the SharePoint REST answers that Atlas reads in the browser when it takes a\r\n# permission snapshot (@ep365/sp-access: who + uniqueBelow), in the same shape (odata=nometadata).\r\n# Atlas replays them through the same code, so the snapshot logic lives in ONE place (Atlas).\r\n# The keys (web url, 'web' | 'list|<list url>' | 'item|<list url>|<id>') follow\r\n# accessCollectTypes.ts - change both together.\r\n\r\n$script:EP365RaQuery = '/roleassignments?$expand=Member,RoleDefinitionBindings&$select=PrincipalId,Member/Title,Member/LoginName,Member/PrincipalType,RoleDefinitionBindings/Id'\r\n$script:EP365ItemsQuery = '/GetList(@l)/items?$select=Id,FileRef,FileLeafRef,Title,FileSystemObjectType,HasUniqueRoleAssignments&$top=5000'\r\n$script:EP365ListsQuery = '/lists?$select=Title,BaseTemplate,HasUniqueRoleAssignments,ItemCount,RootFolder/ServerRelativeUrl&$expand=RootFolder&$filter=Hidden eq false'\r\n\r\nfunction Get-AliasQuery {\r\n    # @l='<server relative url>' (apostrophes doubled, encoded) - like aliasParam in Atlas.\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    return ('@l=' + [Uri]::EscapeDataString(\"'\" + $Path.Replace(\"'\", \"''\") + \"'\"))\r\n}\r\n\r\nfunction Join-Query {\r\n    param([string]$Url, [string]$Query)\r\n    if (-not $Query) { return $Url }\r\n    if ($Url.Contains('?')) { return ($Url + '&' + $Query) }\r\n    return ($Url + '?' + $Query)\r\n}\r\n\r\nfunction Get-SecurableKey {\r\n    param([string]$Kind, [string]$ListUrl, $ItemId)\r\n    if ($Kind -eq 'web') { return 'web' }\r\n    $l = ([string]$ListUrl).ToLowerInvariant().TrimEnd('/')\r\n    if ($Kind -eq 'list') { return ('list|' + $l) }\r\n    return ('item|' + $l + '|' + [string]$ItemId)\r\n}\r\n\r\nfunction Get-EntraGroupId {\r\n    # Entra ID group behind a claim (security group or Microsoft 365 group members); $null for the\r\n    # owners claim (<id>_o) and for anything else - like entraGroupRef in Atlas.\r\n    param([string]$Login)\r\n    $l = ([string]$Login).ToLowerInvariant()\r\n    $isGroup = $l.StartsWith('c:0t.c|tenant|') -or ($l.StartsWith('c:0o.c|federateddirectoryclaimprovider|') -and -not $l.EndsWith('_o'))\r\n    if (-not $isGroup) { return $null }\r\n    return $l.Substring($l.LastIndexOf('|') + 1)\r\n}\r\n\r\nfunction Get-RawWeb {\r\n    # Record of one web: title, role definitions and site collection administrators (read once).\r\n    param([Parameter(Mandatory = $true)]$State, [Parameter(Mandatory = $true)][string]$WebUrl)\r\n    $url = $WebUrl.TrimEnd('/')\r\n    $key = $url.ToLowerInvariant()\r\n    if ($State.Webs.Contains($key)) { return $State.Webs[$key] }\r\n    $api = $url + '/_api/web'\r\n    $wr = Invoke-AccessGet ($api + '?$select=Title,ServerRelativeUrl,HasUniqueRoleAssignments')\r\n    # Parsed answer for the collector itself (HasUniqueRoleAssignments of the root web); not in the file.\r\n    $State.WebJson[$key] = $wr.Json\r\n    $w = [ordered]@{\r\n        url             = $url\r\n        web             = (New-RawResponse $wr)\r\n        roleDefinitions = $null\r\n        siteAdmins      = $null\r\n        lists           = $null\r\n        webs            = $null\r\n        securables      = [ordered]@{}\r\n        items           = [ordered]@{}\r\n        groups          = [ordered]@{}\r\n    }\r\n    if ($w.web.status -ge 200 -and $w.web.status -lt 300) {\r\n        $w.roleDefinitions = New-RawResponse (Invoke-AccessGet ($api + '/roledefinitions?$select=Id,Name,RoleTypeKind,Hidden,BasePermissions'))\r\n        $w.siteAdmins = New-RawResponse (Invoke-AccessGet ($api + '/siteusers?$select=LoginName,Title,IsSiteAdmin&$filter=IsSiteAdmin eq true'))\r\n    }\r\n    $State.Webs[$key] = $w\r\n    return $w\r\n}\r\n\r\nfunction Add-EntraGroup {\r\n    # People in an Entra ID group (transitive), at most 20 pages of 999 - like Atlas in the browser.\r\n    param([Parameter(Mandatory = $true)]$State, [Parameter(Mandatory = $true)][string]$GroupId)\r\n    $id = $GroupId.ToLowerInvariant()\r\n    if ($State.Entra.Contains($id)) { return }\r\n    if ($id -notmatch '^[0-9a-f-]{36}$') { $State.Entra[$id] = [ordered]@{ status = 400; users = $null }; return }\r\n    $users = New-Object System.Collections.Generic.List[object]\r\n    $url = 'https://' + $script:EP365GraphHost + '/v1.0/groups/' + $id + '/transitiveMembers/microsoft.graph.user?$select=id,displayName,userPrincipalName&$top=999'\r\n    $status = 200\r\n    for ($i = 0; $i -lt $script:EP365AccessMaxGraphPages -and $url; $i++) {\r\n        $r = Invoke-AccessGet $url\r\n        if (-not (Test-Ok $r)) { $status = $r.Status; if ($status -lt 400) { $status = 502 }; $users = $null; break }\r\n        foreach ($u in @(Get-ValueList $r.Json)) {\r\n            $users.Add([ordered]@{ id = [string](Get-Prop $u 'id'); displayName = [string](Get-Prop $u 'displayName'); userPrincipalName = [string](Get-Prop $u 'userPrincipalName') })\r\n        }\r\n        $url = ConvertTo-NullableString (Get-JsonValue $r.Json '@odata.nextLink')\r\n    }\r\n    $list = $null\r\n    if ($null -ne $users) { $list = @($users.ToArray()) }\r\n    $State.Entra[$id] = [ordered]@{ status = $status; users = $list }\r\n}\r\n\r\nfunction Add-MembersOf {\r\n    # Members of the SharePoint groups in a role assignment answer, and the Entra ID groups in it.\r\n    param([Parameter(Mandatory = $true)]$State, [Parameter(Mandatory = $true)]$Web, $RaJson)\r\n    foreach ($row in @(Get-ValueList $RaJson)) {\r\n        $type = ConvertTo-NullableInt (Get-Prop $row 'Member.PrincipalType')\r\n        $login = [string](Get-Prop $row 'Member.LoginName')\r\n        $gid = Get-EntraGroupId $login\r\n        if ($gid) { Add-EntraGroup -State $State -GroupId $gid }\r\n        if ($type -ne 8) { continue }\r\n        $groupId = [string](ConvertTo-NullableInt (Get-Prop $row 'PrincipalId'))\r\n        if (-not $groupId -or $Web.groups.Contains($groupId)) { continue }\r\n        $r = Invoke-AccessGet ($Web.url + '/_api/web/sitegroups(' + $groupId + ')/users?$select=LoginName,Title,PrincipalType')\r\n        $Web.groups[$groupId] = New-RawResponse $r\r\n        if (Test-Ok $r) {\r\n            foreach ($m in @(Get-ValueList $r.Json)) {\r\n                $g = Get-EntraGroupId ([string](Get-Prop $m 'LoginName'))\r\n                if ($g) { Add-EntraGroup -State $State -GroupId $g }\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\nfunction Add-SecurableRaw {\r\n    # Role assignments of one securable object (+ its members). $Unique = $null when unknown.\r\n    param([Parameter(Mandatory = $true)]$State, [Parameter(Mandatory = $true)]$Web, [Parameter(Mandatory = $true)][string]$Key,\r\n        [Parameter(Mandatory = $true)][string]$BaseUrl, [string]$Alias, $Unique)\r\n    if ($Web.securables.Contains($Key)) { return }\r\n    $r = Invoke-AccessGet (Join-Query ($BaseUrl + $script:EP365RaQuery) $Alias)\r\n    $Web.securables[$Key] = [ordered]@{ ra = (New-RawResponse $r); unique = $Unique }\r\n    if (Test-Ok $r) { Add-MembersOf -State $State -Web $Web -RaJson $r.Json }\r\n}\r\n\r\nfunction Get-UniqueFlag {\r\n    # HasUniqueRoleAssignments of a list or an item; $null when it cannot be read.\r\n    param([Parameter(Mandatory = $true)][string]$BaseUrl, [string]$Alias)\r\n    $r = Invoke-AccessGet (Join-Query ($BaseUrl + '?$select=HasUniqueRoleAssignments') $Alias)\r\n    if (-not (Test-Ok $r)) { return $null }\r\n    return (ConvertTo-NullableBool (Get-Prop $r.Json 'HasUniqueRoleAssignments'))\r\n}\r\n\r\nfunction Read-ListItems {\r\n    # Items of one list page by page (5000 per page, at most 20000 like Atlas). Stores the pages\r\n    # (rows without own permissions shortened to Id + flag) and returns the rows WITH own permissions.\r\n    param([Parameter(Mandatory = $true)]$Ctx, [Parameter(Mandatory = $true)]$Web, [Parameter(Mandatory = $true)][string]$ListUrl, $ItemCount)\r\n    $key = $ListUrl.ToLowerInvariant().TrimEnd('/')\r\n    $unique = New-Object System.Collections.Generic.List[object]\r\n    if ($Web.items.Contains($key)) { return , $unique.ToArray() }\r\n    $rec = [ordered]@{ pages = @(); more = $false }\r\n    $Web.items[$key] = $rec\r\n    if ($null -ne $ItemCount -and [long]$ItemCount -eq 0) {\r\n        $rec.pages = @([ordered]@{ status = 200; body = [ordered]@{ value = @() } })\r\n        return , $unique.ToArray()\r\n    }\r\n    $pages = New-Object System.Collections.Generic.List[object]\r\n    $url = $Web.url + '/_api/web' + $script:EP365ItemsQuery + '&' + (Get-AliasQuery $ListUrl)\r\n    $read = 0\r\n    while ($url) {\r\n        $r = Invoke-AccessGet $url\r\n        if (-not (Test-Ok $r)) {\r\n            $pages.Add([ordered]@{ status = [int]$r.Status; body = $null })\r\n            break\r\n        }\r\n        $rows = New-Object System.Collections.Generic.List[object]\r\n        $values = @(Get-ValueList $r.Json)\r\n        foreach ($it in $values) {\r\n            $u = (ConvertTo-NullableBool (Get-Prop $it 'HasUniqueRoleAssignments')) -eq $true\r\n            $id = ConvertTo-NullableInt (Get-Prop $it 'Id')\r\n            if (-not $u) { $rows.Add([ordered]@{ Id = $id; HasUniqueRoleAssignments = $false }); continue }\r\n            $row = [ordered]@{\r\n                Id                       = $id\r\n                FileRef                  = (ConvertTo-NullableString (Get-Prop $it 'FileRef'))\r\n                FileLeafRef              = (ConvertTo-NullableString (Get-Prop $it 'FileLeafRef'))\r\n                Title                    = (ConvertTo-NullableString (Get-Prop $it 'Title'))\r\n                FileSystemObjectType     = (ConvertTo-NullableInt (Get-Prop $it 'FileSystemObjectType'))\r\n                HasUniqueRoleAssignments = $true\r\n            }\r\n            $rows.Add($row)\r\n            $unique.Add($row)\r\n        }\r\n        $pages.Add([ordered]@{ status = 200; body = [ordered]@{ value = @($rows.ToArray()) } })\r\n        $read += $values.Count\r\n        $url = ConvertTo-NullableString (Get-JsonValue $r.Json 'odata.nextLink')\r\n        if ($url -and $read -ge $script:EP365AccessMaxItemsPerList) { $rec.more = $true; break }\r\n        if ($url -and -not (Test-ModuleBudget $Ctx)) { $rec.more = $true; break }\r\n    }\r\n    $rec.pages = @($pages.ToArray())\r\n    return , $unique.ToArray()\r\n}\r\n\r\nfunction Add-PlaceRaw {\r\n    # Everything Atlas reads for one snapshot: the place itself, the places below it with their own\r\n    # permissions (subwebs, lists, items - in the order Atlas walks them) up to the snapshot cap.\r\n    param([Parameter(Mandatory = $true)]$Ctx, [Parameter(Mandatory = $true)]$State, [Parameter(Mandatory = $true)]$Place)\r\n    $kind = [string](Get-Prop $Place 'kind')\r\n    $title = [string](Get-Prop $Place 'title')\r\n    $webUrl = ([string](Get-Prop $Place 'webUrl')).TrimEnd('/')\r\n    $srvRel = [string](Get-Prop $Place 'serverRelativeUrl')\r\n    $listUrl = ConvertTo-NullableString (Get-Prop $Place 'listUrl')\r\n    if (-not $listUrl) { $listUrl = $srvRel }\r\n    $itemId = ConvertTo-NullableInt (Get-Prop $Place 'itemId')\r\n    if (-not $webUrl -or $webUrl -notmatch '^https://') { throw ('Place ' + $title + ' has no web address') }\r\n    Write-CollectorLog -Message ('access: ' + $kind + ' ' + $webUrl + ' ' + $srvRel)\r\n    $w = Get-RawWeb -State $State -WebUrl $webUrl\r\n    if ($w.web.status -lt 200 -or $w.web.status -ge 300) {\r\n        Add-ModuleError -Ctx $Ctx -Scope $title -ErrorObject ('The web cannot be read (HTTP ' + $w.web.status + ')')\r\n        return\r\n    }\r\n    $api = $webUrl + '/_api/web'\r\n    $budget = $script:EP365AccessMaxSecurables - 1\r\n\r\n    # ---- the place itself ----\r\n    if ($kind -eq 'web') {\r\n        $webJson = $State.WebJson[$webUrl.ToLowerInvariant()]\r\n        Add-SecurableRaw -State $State -Web $w -Key 'web' -BaseUrl $api -Unique (ConvertTo-NullableBool (Get-Prop $webJson 'HasUniqueRoleAssignments'))\r\n    } elseif ($kind -eq 'library' -or $kind -eq 'list') {\r\n        $alias = Get-AliasQuery $listUrl\r\n        Add-SecurableRaw -State $State -Web $w -Key (Get-SecurableKey 'list' $listUrl) -BaseUrl ($api + '/GetList(@l)') -Alias $alias -Unique (Get-UniqueFlag -BaseUrl ($api + '/GetList(@l)') -Alias $alias)\r\n    } else {\r\n        if ($null -eq $itemId) { Add-ModuleError -Ctx $Ctx -Scope $title -ErrorObject 'The place has no list item id'; return }\r\n        $alias = Get-AliasQuery $listUrl\r\n        $base = $api + '/GetList(@l)/items(' + $itemId + ')'\r\n        Add-SecurableRaw -State $State -Web $w -Key (Get-SecurableKey 'item' $listUrl $itemId) -BaseUrl $base -Alias $alias -Unique (Get-UniqueFlag -BaseUrl $base -Alias $alias)\r\n    }\r\n    if ($kind -eq 'file' -or $kind -eq 'item') { return }\r\n\r\n    # ---- places below it, in the order of uniqueBelow ----\r\n    $lists = @()\r\n    if ($kind -eq 'web') {\r\n        $lr = Invoke-AccessGet ($api + $script:EP365ListsQuery)\r\n        $w.lists = New-RawResponse $lr\r\n        $wr = Invoke-AccessGet ($api + '/webs?$select=Title,ServerRelativeUrl,HasUniqueRoleAssignments')\r\n        $w.webs = New-RawResponse $wr\r\n        if (-not (Test-Ok $lr)) { Add-ModuleError -Ctx $Ctx -Scope $title -ErrorObject ('Lists of the web cannot be read (HTTP ' + $lr.Status + ')'); return }\r\n        $origin = ([string](Get-Prop $State.Preset 'tenantUrl')).TrimEnd('/')\r\n        if (Test-Ok $wr) {\r\n            $subs = @(Get-ValueList $wr.Json | Sort-Object -Property @{ Expression = { [string]$_.Title } } -Culture 'cs-CZ')\r\n            foreach ($s in $subs) {\r\n                if ((ConvertTo-NullableBool (Get-Prop $s 'HasUniqueRoleAssignments')) -ne $true) { continue }\r\n                if ($budget -le 0 -or -not (Test-ModuleBudget $Ctx)) { break }\r\n                $subUrl = $origin + [string](Get-Prop $s 'ServerRelativeUrl')\r\n                $sw = Get-RawWeb -State $State -WebUrl $subUrl\r\n                if ($sw.web.status -ge 200 -and $sw.web.status -lt 300) { Add-SecurableRaw -State $State -Web $sw -Key 'web' -BaseUrl ($subUrl + '/_api/web') -Unique $true }\r\n                $budget--\r\n            }\r\n        }\r\n        $lists = @(Get-ValueList $lr.Json | Sort-Object -Property @{ Expression = { [string]$_.Title } } -Culture 'cs-CZ' | ForEach-Object {\r\n                [pscustomobject]@{ Url = [string](Get-Prop $_ 'RootFolder.ServerRelativeUrl'); Unique = ((ConvertTo-NullableBool (Get-Prop $_ 'HasUniqueRoleAssignments')) -eq $true); ItemCount = (ConvertTo-NullableLong (Get-Prop $_ 'ItemCount')) }\r\n            } | Where-Object { $_.Url })\r\n        foreach ($l in $lists) {\r\n            if (-not $l.Unique) { continue }\r\n            if ($budget -le 0 -or -not (Test-ModuleBudget $Ctx)) { break }\r\n            Add-SecurableRaw -State $State -Web $w -Key (Get-SecurableKey 'list' $l.Url) -BaseUrl ($api + '/GetList(@l)') -Alias (Get-AliasQuery $l.Url) -Unique $true\r\n            $budget--\r\n        }\r\n    } else {\r\n        $lists = @([pscustomobject]@{ Url = $listUrl; Unique = $null; ItemCount = $null })\r\n    }\r\n    $under = ''\r\n    if ($kind -eq 'folder') { $under = $srvRel.ToLowerInvariant().TrimEnd('/') + '/' }\r\n    foreach ($l in $lists) {\r\n        if (-not (Test-ModuleBudget $Ctx)) { break }\r\n        $rows = Read-ListItems -Ctx $Ctx -Web $w -ListUrl $l.Url -ItemCount $l.ItemCount\r\n        foreach ($row in $rows) {\r\n            if ($under -and -not ([string]$row.FileRef).ToLowerInvariant().StartsWith($under)) { continue }\r\n            if ($budget -le 0 -or -not (Test-ModuleBudget $Ctx)) { break }\r\n            Add-SecurableRaw -State $State -Web $w -Key (Get-SecurableKey 'item' $l.Url $row.Id) -BaseUrl ($api + '/GetList(@l)/items(' + $row.Id + ')') -Alias (Get-AliasQuery $l.Url) -Unique $true\r\n            $budget--\r\n        }\r\n    }\r\n    if ($budget -le 0) { $Ctx.PartialReason = ('Place ' + $title + ': more than ' + $script:EP365AccessMaxSecurables + ' places with own permissions; the rest was not read (same cap as Atlas)') }\r\n}\r\n\r\nfunction Get-AccessModuleData {\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    $preset = $script:EP365State.Preset\r\n    $places = @(Get-AccessPlaces $preset)\r\n    if ($places.Count -eq 0) { $Ctx.SkipReason = 'No place is chosen in Atlas for the scheduled collection'; return @{ Data = $null; Records = $null } }\r\n    $state = @{ Webs = [ordered]@{}; WebJson = @{}; Entra = [ordered]@{}; Preset = $preset }\r\n    $done = 0\r\n    foreach ($p in $places) {\r\n        if (-not (Test-ModuleBudget $Ctx)) { break }\r\n        try { Add-PlaceRaw -Ctx $Ctx -State $state -Place $p; $done++ }\r\n        catch { Add-ModuleError -Ctx $Ctx -Scope ([string](Get-Prop $p 'title')) -ErrorObject $_ }\r\n    }\r\n    $data = [ordered]@{\r\n        places = @($places)\r\n        webs   = @($state.Webs.Values)\r\n        entra  = $state.Entra\r\n        limits = [ordered]@{ maxSecurablesPerPlace = $script:EP365AccessMaxSecurables; maxItemsPerList = $script:EP365AccessMaxItemsPerList }\r\n    }\r\n    return @{ Data = $data; Records = $done }\r\n}\r\n\r\n# ===================== access 30: module 'sitesSelected' - which applications have Sites.Selected grants where =====================\r\n#\r\n# Microsoft Graph, application permission Sites.FullControl.All:\r\n#   GET /sites/getAllSites                     all sites of the tenant (paged; OneDrive skipped by default)\r\n#   GET /sites/{id}/permissions                grants of applications on the site (Sites.Selected)\r\n#   GET /sites/{id}/permissions/{permId}       roles, when the list answer has none\r\n#   GET /sites/{id}/lists, /lists/{id}/permissions   only with includeLists (one request per list)\r\n# Only sites (and lists) where some application has a grant go into the file; sites whose grants\r\n# cannot be read are listed in 'failed' - never reported as \"no application\".\r\n\r\nfunction Get-PermissionGrants {\r\n    # Applications and roles of a Graph permission list: [{ appId, appName, roles }].\r\n    param($Permissions, [Parameter(Mandatory = $true)][string]$RolesUrlBase)\r\n    $byApp = [ordered]@{}\r\n    foreach ($perm in @($Permissions)) {\r\n        $apps = New-Object System.Collections.Generic.List[object]\r\n        foreach ($path in @('grantedToIdentitiesV2', 'grantedToIdentities')) {\r\n            foreach ($g in @(Get-PropList $perm $path)) { $a = Get-Prop $g 'application'; if ($null -ne $a) { $apps.Add($a) } }\r\n        }\r\n        foreach ($path in @('grantedToV2.application', 'grantedTo.application')) { $a = Get-Prop $perm $path; if ($null -ne $a) { $apps.Add($a) } }\r\n        if ($apps.Count -eq 0) { continue }\r\n        $roles = @(Get-StringList (Get-Prop $perm 'roles'))\r\n        $permId = ConvertTo-NullableString (Get-Prop $perm 'id')\r\n        if ($roles.Count -eq 0 -and $permId) {\r\n            $one = Invoke-AccessGet ($RolesUrlBase + '/' + [Uri]::EscapeDataString($permId))\r\n            if (Test-Ok $one) { $roles = @(Get-StringList (Get-Prop $one.Json 'roles')) }\r\n        }\r\n        foreach ($a in $apps) {\r\n            $appId = ([string](Get-Prop $a 'id')).ToLowerInvariant()\r\n            if (-not $appId) { continue }\r\n            if (-not $byApp.Contains($appId)) { $byApp[$appId] = [ordered]@{ appId = $appId; appName = [string](Get-Prop $a 'displayName'); roles = (New-Object System.Collections.Generic.List[string]) } }\r\n            foreach ($r in $roles) { $rl = $r.ToLowerInvariant(); if (-not $byApp[$appId].roles.Contains($rl)) { $byApp[$appId].roles.Add($rl) } }\r\n        }\r\n    }\r\n    $out = New-Object System.Collections.Generic.List[object]\r\n    foreach ($v in $byApp.Values) { $out.Add([ordered]@{ appId = $v.appId; appName = $v.appName; roles = @($v.roles.ToArray()) }) }\r\n    return , $out.ToArray()\r\n}\r\n\r\nfunction Get-GraphPages {\r\n    # All pages of a Graph list (up to $MaxPages); returns @{ Status; Items } - Status of the failing page or 200.\r\n    param([Parameter(Mandatory = $true)][string]$Url, [int]$MaxPages = 1000, $Ctx)\r\n    $items = New-Object System.Collections.Generic.List[object]\r\n    $next = $Url\r\n    for ($i = 0; $i -lt $MaxPages -and $next; $i++) {\r\n        if ($null -ne $Ctx -and -not (Test-ModuleBudget $Ctx)) { return @{ Status = 200; Items = $items.ToArray(); Cut = $true } }\r\n        $r = Invoke-AccessGet $next\r\n        if (-not (Test-Ok $r)) { return @{ Status = $r.Status; Items = $items.ToArray(); Cut = $true } }\r\n        foreach ($x in @(Get-ValueList $r.Json)) { $items.Add($x) }\r\n        $next = ConvertTo-NullableString (Get-JsonValue $r.Json '@odata.nextLink')\r\n    }\r\n    return @{ Status = 200; Items = $items.ToArray(); Cut = [bool]$next }\r\n}\r\n\r\nfunction Get-SitesSelectedModuleData {\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    $preset = $script:EP365State.Preset\r\n    if ((ConvertTo-NullableBool (Get-Prop $preset 'sitesSelected')) -ne $true) {\r\n        $Ctx.SkipReason = 'Not chosen in Atlas for the scheduled collection'\r\n        return @{ Data = $null; Records = $null }\r\n    }\r\n    $includeLists = (ConvertTo-NullableBool (Get-Prop $preset 'includeLists')) -eq $true\r\n    $includeOneDrive = (ConvertTo-NullableBool (Get-Prop $preset 'includeOneDrive')) -eq $true\r\n    $graph = 'https://' + $script:EP365GraphHost + '/v1.0'\r\n\r\n    $all = Get-GraphPages -Url ($graph + '/sites/getAllSites?$select=id,webUrl,displayName,name,isPersonalSite') -Ctx $Ctx\r\n    if ($all.Status -eq 400) { $all = Get-GraphPages -Url ($graph + '/sites/getAllSites') -Ctx $Ctx }\r\n    if ($all.Status -lt 200 -or $all.Status -ge 300) { throw ('The list of sites cannot be read (HTTP ' + $all.Status + '). Does the application have Sites.FullControl.All (Microsoft Graph) with admin consent?') }\r\n    if ($all.Cut) { $Ctx.PartialReason = 'The list of sites was not read to the end' }\r\n    $sites = New-Object System.Collections.Generic.List[object]\r\n    foreach ($s in @($all.Items)) {\r\n        $url = [string](Get-Prop $s 'webUrl')\r\n        $personal = ((ConvertTo-NullableBool (Get-Prop $s 'isPersonalSite')) -eq $true) -or ($url -match '(?i)^https://[a-z0-9-]+-my\\.sharepoint\\.com/')\r\n        if ($personal -and -not $includeOneDrive) { continue }\r\n        $sites.Add($s)\r\n    }\r\n    Write-CollectorLog -Message ('sitesSelected: ' + $sites.Count + ' site(s) to check')\r\n\r\n    $out = New-Object System.Collections.Generic.List[object]\r\n    $failed = New-Object System.Collections.Generic.List[object]\r\n    $scanned = 0\r\n    foreach ($s in $sites) {\r\n        if (-not (Test-ModuleBudget $Ctx)) { $Ctx.PartialReason = ('Checked ' + $scanned + ' of ' + $sites.Count + ' sites'); break }\r\n        $id = [string](Get-Prop $s 'id')\r\n        $url = [string](Get-Prop $s 'webUrl')\r\n        $scanned++\r\n        $permBase = $graph + '/sites/' + $id + '/permissions'\r\n        $r = Invoke-AccessGet $permBase\r\n        if (-not (Test-Ok $r)) { $failed.Add([ordered]@{ webUrl = $url; status = [int]$r.Status }); continue }\r\n        $grants = Get-PermissionGrants -Permissions @(Get-ValueList $r.Json) -RolesUrlBase $permBase\r\n        $listGrants = New-Object System.Collections.Generic.List[object]\r\n        if ($includeLists) {\r\n            $ls = Get-GraphPages -Url ($graph + '/sites/' + $id + '/lists?$select=id,displayName,webUrl,list') -Ctx $Ctx\r\n            if ($ls.Status -lt 200 -or $ls.Status -ge 300) { Add-ModuleError -Ctx $Ctx -Scope $url -ErrorObject ('Lists cannot be read (HTTP ' + $ls.Status + ')') }\r\n            foreach ($l in @($ls.Items)) {\r\n                if ((ConvertTo-NullableBool (Get-Prop $l 'list.hidden')) -eq $true) { continue }\r\n                $lid = [string](Get-Prop $l 'id')\r\n                $lBase = $graph + '/sites/' + $id + '/lists/' + $lid + '/permissions'\r\n                $lr = Invoke-AccessGet $lBase\r\n                if (-not (Test-Ok $lr)) { Add-ModuleError -Ctx $Ctx -Scope ([string](Get-Prop $l 'webUrl')) -ErrorObject ('List permissions cannot be read (HTTP ' + $lr.Status + ')'); continue }\r\n                $lg = Get-PermissionGrants -Permissions @(Get-ValueList $lr.Json) -RolesUrlBase $lBase\r\n                if ($lg.Count -gt 0) { $listGrants.Add([ordered]@{ id = $lid; title = [string](Get-Prop $l 'displayName'); webUrl = [string](Get-Prop $l 'webUrl'); grants = $lg }) }\r\n            }\r\n        }\r\n        if ($grants.Count -eq 0 -and $listGrants.Count -eq 0) { continue }\r\n        $site = [ordered]@{ id = $id; webUrl = $url; title = [string](Get-Prop $s 'displayName'); grants = $grants }\r\n        if ($includeLists) { $site.lists = @($listGrants.ToArray()) }\r\n        $out.Add($site)\r\n    }\r\n    if ($failed.Count -gt 0) { Add-ModuleError -Ctx $Ctx -Scope 'sites' -ErrorObject ($failed.Count.ToString() + ' site(s): permissions cannot be read (first HTTP ' + $failed[0].status + ')') }\r\n    $data = [ordered]@{\r\n        total           = $sites.Count\r\n        scanned         = $scanned\r\n        includeLists    = $includeLists\r\n        includeOneDrive = $includeOneDrive\r\n        sites           = @($out.ToArray())\r\n        failed          = @($failed.ToArray())\r\n    }\r\n    return @{ Data = $data; Records = $out.Count }\r\n}\r\n\r\n# ===================== access 50: run, queue, upload, connection test, install, uninstall =====================\r\n#\r\n# Folder C:\\ProgramData\\EP365AtlasAccess (SYSTEM, Administrators, the task account):\r\n#   collector.json    configuration of -Install (ids, thumbprint, schedule - no secret)\r\n#   certificate.json  the certificate of -NewCertificate\r\n#   state.json        last upload and last error\r\n#   out\\ queue\\ logs\\ work folders, snapshots waiting for upload, one log per day (14 days)\r\n\r\nfunction Read-AccessConfig {\r\n    param([Parameter(Mandatory = $true)]$Paths, [switch]$ForUpload)\r\n    $cfg = $null\r\n    try { $cfg = Read-JsonFile $Paths.Config } catch { throw ('The configuration ' + $Paths.Config + ' is damaged: ' + (Format-ErrorText $_) + '. Run -Install again.') }\r\n    if ($null -eq $cfg) { throw ('The collector is not installed (' + $Paths.Config + ' is missing). Run -NewCertificate, Register-EP365AtlasAccessCollectApp.ps1 and -Install first.') }\r\n    $keys = @('tenantId', 'clientId', 'certificateThumbprint')\r\n    if ($ForUpload) { $keys += @('driveId', 'inboxItemId') }\r\n    foreach ($k in $keys) {\r\n        if ($null -eq (ConvertTo-NullableString (Get-Prop $cfg $k))) { throw ('The configuration has no ' + $k + '. Run -Install again with the values from Register-EP365AtlasAccessCollectApp.ps1.') }\r\n    }\r\n    return $cfg\r\n}\r\n\r\nfunction Open-AccessSession {\r\n    # Configuration + certificate + sign-in session; the tenant of the configuration must be the\r\n    # tenant this copy of the script was downloaded for.\r\n    param([Parameter(Mandatory = $true)]$Paths, [Parameter(Mandatory = $true)]$Preset, [switch]$ForUpload)\r\n    $cfg = Read-AccessConfig -Paths $Paths -ForUpload:$ForUpload\r\n    if ([string](Get-Prop $cfg 'tenantId') -ne ([string](Get-Prop $Preset 'tenantId')).ToLowerInvariant()) {\r\n        throw ('This script was downloaded for tenant ' + (Get-Prop $Preset 'tenantId') + ', the collector is installed for ' + (Get-Prop $cfg 'tenantId') + '.')\r\n    }\r\n    $cert = Find-CollectorCertificate ([string](Get-Prop $cfg 'certificateThumbprint'))\r\n    if ($null -eq $cert) { throw ('Certificate ' + (Get-Prop $cfg 'certificateThumbprint') + ' is not in LocalMachine\\My. Run -NewCertificate and -Install again.') }\r\n    if (-not $cert.HasPrivateKey) { throw 'This account cannot use the private key of the collector certificate (run -Install again to grant access).' }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow) { throw ('The collector certificate expired on ' + $cert.NotAfter.ToString('yyyy-MM-dd') + '. Run -NewCertificate, register the new .cer file and run -Install again.') }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow.AddDays(30)) { Write-CollectorLog -Level WARN -Message ('The collector certificate expires on ' + $cert.NotAfter.ToString('yyyy-MM-dd') + '; renew it with -NewCertificate and register the new .cer file.') }\r\n    Initialize-GraphSession -Config $cfg -Certificate $cert\r\n    $script:EP365Graph.ResourceTokens = @{}\r\n    return @{ Config = $cfg; Certificate = $cert }\r\n}\r\n\r\nfunction Invoke-EP365AccessCollectMain {\r\n    # One collection: modules -> manifest -> ZIP in -OutputPath. Needs an open session.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$OutputPath,\r\n        [Parameter(Mandatory = $true)]$Preset,\r\n        [string[]]$Modules,\r\n        [int]$ModuleTimeoutMinutes = 120,\r\n        [ValidateSet('Export', 'Upload')][string]$Mode = 'Export'\r\n    )\r\n    $startedAt = Get-UtcNowIso\r\n    $out = Resolve-CollectorOutputPath $OutputPath\r\n    $work = Join-Path $out ('ep365-work-' + [DateTime]::UtcNow.ToString('yyyyMMddHHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0, 6))\r\n    [void](New-Item -ItemType Directory -Path $work -Force)\r\n    $script:EP365State = @{ OutputPath = $out; WorkDir = $work; LogPath = (Join-Path $work 'collector.log'); Cache = @{}; Anonymize = $false; Preset = $Preset }\r\n    $script:EP365AccessRaw.Clear()\r\n    $account = $null\r\n    try { $account = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { $account = [string]$env:USERDOMAIN + '\\' + [string]$env:USERNAME }\r\n    $psVersion = $PSVersionTable.PSVersion.ToString()\r\n    $selected = @($script:EP365AccessModules)\r\n    if ($Modules -and $Modules.Count -gt 0) { $selected = @($script:EP365AccessModules | Where-Object { $Modules -contains $_ }) }\r\n    Write-CollectorLog -Message ('EP365 Atlas access collector {0} (schema {1}), Windows PowerShell {2}, host {3}, account {4}' -f $script:EP365AccessCollectorVersion, $script:EP365SchemaVersion, $psVersion, $env:COMPUTERNAME, $account)\r\n    Write-CollectorLog -Message ('Tenant {0}, {1} place(s), modules {2}, budget {3} min' -f (Get-Prop $Preset 'tenantUrl'), @(Get-AccessPlaces $Preset).Count, ($selected -join ','), $ModuleTimeoutMinutes)\r\n    try {\r\n        $entries = New-Object System.Collections.Generic.List[object]\r\n        foreach ($id in $script:EP365AccessModules) {\r\n            if ($selected -notcontains $id) {\r\n                $entries.Add([pscustomobject][ordered]@{ id = $id; file = $null; status = 'skipped'; durationSec = 0; records = $null; error = 'Not selected' })\r\n                continue\r\n            }\r\n            $entries.Add((Invoke-CollectorModule -Id $id -BudgetMinutes $ModuleTimeoutMinutes))\r\n            $script:EP365AccessRaw.Clear()\r\n        }\r\n        $manifest = [ordered]@{\r\n            schemaVersion = $script:EP365SchemaVersion\r\n            kind          = $script:EP365SnapshotKind\r\n            tenantId      = ([string](Get-Prop $Preset 'tenantId')).ToLowerInvariant()\r\n            tenantUrl     = [string](Get-Prop $Preset 'tenantUrl')\r\n            collectedAt   = $startedAt\r\n            finishedAt    = Get-UtcNowIso\r\n            collector     = [ordered]@{ version = $script:EP365AccessCollectorVersion; host = [string]$env:COMPUTERNAME; account = [string]$account; mode = $Mode; powershell = $psVersion }\r\n            modules       = @($entries.ToArray())\r\n        }\r\n        Save-Manifest $manifest\r\n        $stem = 'ep365-access-' + [DateTime]::UtcNow.ToString('yyyyMMdd-HHmm', $script:EP365Invariant)\r\n        $zipBase = $stem\r\n        $n = 1\r\n        while (Test-Path -LiteralPath (Join-Path $out ($zipBase + '.zip'))) { $n++; $zipBase = $stem + '-' + $n }\r\n        $zipPath = Join-Path $out ($zipBase + '.zip')\r\n        Write-CollectorLog -Message ('Packaging ' + $zipBase + '.zip')\r\n        $script:EP365State.LogPath = $null\r\n        $files = @(Get-ChildItem -LiteralPath $work -File | ForEach-Object { $_.FullName })\r\n        Compress-Archive -LiteralPath $files -DestinationPath $zipPath -CompressionLevel Optimal -ErrorAction Stop\r\n        if ((Split-Path -Leaf $work) -like 'ep365-work-*' -and $work.StartsWith($out, [System.StringComparison]::OrdinalIgnoreCase)) { [System.IO.Directory]::Delete($work, $true) }\r\n        if (-not $script:EP365Quiet) {\r\n            Write-Host ''\r\n            Write-Host 'EP365 Atlas access snapshot' -ForegroundColor Cyan\r\n            foreach ($e in $entries) {\r\n                $color = 'Gray'\r\n                if ($e.status -eq 'ok') { $color = 'Green' } elseif ($e.status -eq 'partial') { $color = 'Yellow' } elseif ($e.status -eq 'failed') { $color = 'Red' }\r\n                Write-Host ('  {0,-14} {1,-8} {2,8} s  {3}' -f $e.id, $e.status, ([string]$e.durationSec), ([string]$e.error)) -ForegroundColor $color\r\n            }\r\n            Write-Host ('Snapshot: ' + $zipPath)\r\n        }\r\n        return [pscustomobject]@{ ZipPath = $zipPath; Manifest = $manifest }\r\n    } catch {\r\n        Write-CollectorLog -Level ERROR -Message ('Collector failed: ' + (Format-ErrorText $_))\r\n        if (-not $script:EP365Quiet) { Write-Host ('The work folder with collector.log is kept for diagnostics: ' + $work) -ForegroundColor Yellow }\r\n        throw\r\n    }\r\n}\r\n\r\nfunction Resolve-CollectorOutputPath {\r\n    param([string]$Path)\r\n    if ([string]::IsNullOrWhiteSpace($Path)) { throw '-OutputPath is required' }\r\n    if (-not ($Path -match '^[A-Za-z]:\\\\' -or $Path -match '^\\\\\\\\[^\\\\]+\\\\[^\\\\]+')) { throw ('-OutputPath must be an absolute path (for example D:\\EP365AtlasAccess): ' + $Path) }\r\n    $full = [System.IO.Path]::GetFullPath($Path).TrimEnd('\\')\r\n    if (-not (Test-Path -LiteralPath $full)) { [void](New-Item -ItemType Directory -Path $full -Force) }\r\n    return $full\r\n}\r\n\r\nfunction Test-AccessZip {\r\n    # A queued file must be a snapshot of this collector for this tenant (name, ZIP, manifest kind, tenant).\r\n    param([Parameter(Mandatory = $true)][string]$Path, [Parameter(Mandatory = $true)][string]$TenantId)\r\n    $name = [System.IO.Path]::GetFileName($Path)\r\n    if ($name -notmatch $script:EP365AccessZipRx) { throw ('Not a snapshot of the access collector: ' + $name) }\r\n    if ((New-Object System.IO.FileInfo $Path).Length -gt $script:EP365MaxSnapshotBytes) { throw ($name + ' is larger than 300 MB; Atlas does not import such a snapshot.') }\r\n    Add-Type -AssemblyName System.IO.Compression\r\n    Add-Type -AssemblyName System.IO.Compression.FileSystem\r\n    $zip = $null\r\n    try { $zip = [System.IO.Compression.ZipFile]::OpenRead($Path) } catch { throw ('Not a readable ZIP file: ' + $name) }\r\n    $text = $null\r\n    try {\r\n        $entry = @($zip.Entries | Where-Object { $_.Name -eq 'manifest.json' }) | Select-Object -First 1\r\n        if ($null -eq $entry) { throw ($name + ' has no manifest.json.') }\r\n        $reader = New-Object System.IO.StreamReader ($entry.Open(), $script:EP365Utf8NoBom)\r\n        try { $text = $reader.ReadToEnd() } finally { $reader.Close() }\r\n    } finally { $zip.Dispose() }\r\n    $m = ConvertFrom-Json -InputObject $text\r\n    if ([string](Get-Prop $m 'kind') -ne $script:EP365SnapshotKind) { throw ('manifest.json in ' + $name + ' is not an access snapshot manifest.') }\r\n    if ([string](Get-Prop $m 'tenantId') -ne $TenantId.ToLowerInvariant()) { throw ($name + ' belongs to tenant ' + (Get-Prop $m 'tenantId') + '.') }\r\n}\r\n\r\nfunction Send-AccessQueue {\r\n    # Uploads the queue oldest first into Inbox/<tenant id>. A file leaves the queue only after the\r\n    # library confirmed its full size; an unreadable file goes to queue\\rejected (never deleted).\r\n    param([Parameter(Mandatory = $true)]$Paths, [Parameter(Mandatory = $true)][string]$TenantId)\r\n    $state = $null\r\n    try { $state = Read-JsonFile $Paths.State } catch { $state = $null }\r\n    $st = [ordered]@{ lastUploadAt = (ConvertTo-NullableString (Get-Prop $state 'lastUploadAt')); lastUploadFile = (ConvertTo-NullableString (Get-Prop $state 'lastUploadFile')); lastErrorAt = (ConvertTo-NullableString (Get-Prop $state 'lastErrorAt')); lastError = (ConvertTo-NullableString (Get-Prop $state 'lastError')) }\r\n    $uploaded = 0\r\n    $errorText = $null\r\n    foreach ($f in @(Get-QueueFiles $Paths.Queue)) {\r\n        try { Test-AccessZip -Path $f.FullName -TenantId $TenantId }\r\n        catch {\r\n            $dir = Join-Path $Paths.Queue 'rejected'\r\n            if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }\r\n            $to = Join-Path $dir ([DateTime]::UtcNow.ToString('yyyyMMddHHmmss', $script:EP365Invariant) + '-' + $f.Name)\r\n            [System.IO.File]::Move($f.FullName, $to)\r\n            Write-CollectorLog -Level ERROR -Message ('queue: ' + $f.Name + ' moved to ' + $to + ': ' + (Format-ErrorText $_))\r\n            continue\r\n        }\r\n        try {\r\n            [void](Send-InboxFile -Path $f.FullName -SpFarmId $TenantId.ToLowerInvariant())\r\n            [System.IO.File]::Delete($f.FullName)\r\n            $uploaded++\r\n            $st.lastUploadAt = Get-UtcNowIso\r\n            $st.lastUploadFile = $f.Name\r\n            Write-CollectorLog -Message ('queue: ' + $f.Name + ' uploaded to Inbox/' + $TenantId.ToLowerInvariant())\r\n        } catch {\r\n            $errorText = Format-ErrorText $_\r\n            $st.lastErrorAt = Get-UtcNowIso\r\n            $st.lastError = $errorText\r\n            Write-CollectorLog -Level ERROR -Message ('queue: ' + $f.Name + ' not uploaded, stays in the queue: ' + $errorText)\r\n            break\r\n        }\r\n    }\r\n    if ($null -eq $errorText -and $uploaded -gt 0) { $st.lastError = $null }\r\n    Write-JsonFile -Path $Paths.State -Object $st\r\n    return [pscustomobject]@{ Uploaded = $uploaded; Remaining = @(Get-QueueFiles $Paths.Queue).Count; Error = $errorText }\r\n}\r\n\r\nfunction Invoke-EP365AccessUploadRun {\r\n    # The scheduled task: collect -> queue -> upload of the whole queue.\r\n    param([string]$Root, [string[]]$Modules, [int]$ModuleTimeoutMinutes = 120)\r\n    $preset = Get-AccessPreset\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-TaskLog $paths\r\n    Write-CollectorLog -Message 'Scheduled run: access snapshot and upload'\r\n    [void](Open-AccessSession -Paths $paths -Preset $preset -ForUpload)\r\n    foreach ($d in @($paths.Out, $paths.Queue)) { if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) } }\r\n    $res = Invoke-EP365AccessCollectMain -OutputPath $paths.Out -Preset $preset -Modules $Modules -ModuleTimeoutMinutes $ModuleTimeoutMinutes -Mode Upload\r\n    $name = [System.IO.Path]::GetFileName($res.ZipPath)\r\n    [System.IO.File]::Move($res.ZipPath, (Join-Path $paths.Queue $name))\r\n    Write-CollectorLog -Message ('queue: ' + $name + ' added')\r\n    [void](Limit-CollectorQueue -QueueDir $paths.Queue)\r\n    return (Send-AccessQueue -Paths $paths -TenantId ([string](Get-Prop $preset 'tenantId')))\r\n}\r\n\r\nfunction Invoke-EP365AccessExport {\r\n    param([Parameter(Mandatory = $true)][string]$OutputPath, [string[]]$Modules, [int]$ModuleTimeoutMinutes = 120, [string]$Root)\r\n    $preset = Get-AccessPreset\r\n    [void](Open-AccessSession -Paths (Get-CollectorPaths $Root) -Preset $preset)\r\n    return (Invoke-EP365AccessCollectMain -OutputPath $OutputPath -Preset $preset -Modules $Modules -ModuleTimeoutMinutes $ModuleTimeoutMinutes -Mode Export)\r\n}\r\n\r\nfunction Invoke-EP365AccessTestConnection {\r\n    # Sign-in and one read per permission. Returns the number of failed checks.\r\n    param([string]$Root)\r\n    $preset = Get-AccessPreset\r\n    $paths = Get-CollectorPaths $Root\r\n    $session = Open-AccessSession -Paths $paths -Preset $preset\r\n    $script:EP365State = @{ Cache = @{}; Preset = $preset; WorkDir = $null; LogPath = $null; Anonymize = $false }\r\n    $tenantUrl = [string](Get-Prop $preset 'tenantUrl')\r\n    $graph = 'https://' + $script:EP365GraphHost + '/v1.0'\r\n    $checks = @(\r\n        @{ Name = 'SharePoint (Sites.FullControl.All): role assignments of the root site'; Url = ($tenantUrl + '/_api/web/roleassignments?$top=1') },\r\n        @{ Name = 'Microsoft Graph (Sites.FullControl.All): sites'; Url = ($graph + '/sites/root?$select=id,webUrl') },\r\n        @{ Name = 'Microsoft Graph (GroupMember.Read.All): groups'; Url = ($graph + '/groups?$top=1&$select=id') }\r\n    )\r\n    $bad = 0\r\n    foreach ($c in $checks) {\r\n        $r = $null\r\n        try { $r = Invoke-AccessGet -Uri $c.Url -MaxAttempts 2 } catch { $r = @{ Status = 0; Text = (Format-ErrorText $_); Json = $null } }\r\n        if ($r.Status -ge 200 -and $r.Status -lt 300) { Write-Host ('  OK    ' + $c.Name) -ForegroundColor Green }\r\n        else { $bad++; Write-Host ('  FAIL  ' + $c.Name + ' (HTTP ' + $r.Status + ')') -ForegroundColor Red }\r\n    }\r\n    $places = @(Get-AccessPlaces $preset)\r\n    foreach ($p in $places) {\r\n        $u = ([string](Get-Prop $p 'webUrl')).TrimEnd('/') + '/_api/web?$select=Title'\r\n        $r = $null\r\n        try { $r = Invoke-AccessGet -Uri $u -MaxAttempts 2 } catch { $r = @{ Status = 0 } }\r\n        if ($r.Status -ge 200 -and $r.Status -lt 300) { Write-Host ('  OK    place ' + (Get-Prop $p 'webUrl')) -ForegroundColor Green }\r\n        else { $bad++; Write-Host ('  FAIL  place ' + (Get-Prop $p 'webUrl') + ' (HTTP ' + $r.Status + ')') -ForegroundColor Red }\r\n    }\r\n    if (ConvertTo-NullableString (Get-Prop $session.Config 'inboxItemId')) {\r\n        try { Write-Host ('  OK    ' + (Test-InboxAccess)) -ForegroundColor Green }\r\n        catch { $bad++; Write-Host ('  FAIL  Inbox: ' + (Format-ErrorText $_)) -ForegroundColor Red }\r\n    } else {\r\n        Write-Host '  --    Inbox: not configured (-NoTasks); snapshots are imported by hand in Atlas.'\r\n    }\r\n    Write-Host ''\r\n    Write-Host 'Note: Sites.FullControl.All lets the application read and change every site of the tenant. The collector itself only reads (and uploads into the Inbox folder); keep the certificate on a protected server.' -ForegroundColor Yellow\r\n    return $bad\r\n}\r\n\r\nfunction New-EP365AccessCertificate {\r\n    param([string]$Root)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-CollectorFolder -Paths $paths\r\n    $cerPath = Join-Path $paths.Root 'ep365-atlas-access-collector.cer'\r\n    $info = $null\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n    $cert = $null\r\n    $old = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n    if ($old) {\r\n        $c = Find-CollectorCertificate $old\r\n        if ($null -ne $c -and $c.HasPrivateKey -and $c.NotAfter.ToUniversalTime() -gt [DateTime]::UtcNow.AddDays(30)) { $cert = $c }\r\n    }\r\n    $created = $false\r\n    if ($null -eq $cert) {\r\n        $cert = New-SelfSignedCertificate -Subject ('CN=EP365 Atlas access collector ' + $env:COMPUTERNAME) -FriendlyName 'EP365 Atlas access collector' `\r\n            -CertStoreLocation 'Cert:\\LocalMachine\\My' -Provider 'Microsoft Software Key Storage Provider' -KeyAlgorithm RSA -KeyLength 2048 `\r\n            -HashAlgorithm SHA256 -KeyExportPolicy NonExportable -KeyUsage DigitalSignature -Type Custom -NotAfter ([DateTime]::Now.AddYears(2))\r\n        $created = $true\r\n    }\r\n    [System.IO.File]::WriteAllBytes($cerPath, $cert.RawData)\r\n    Write-JsonFile -Path $paths.Certificate -Object ([ordered]@{ thumbprint = $cert.Thumbprint; subject = $cert.Subject; notAfter = (ConvertTo-IsoUtc $cert.NotAfter); cerFile = $cerPath })\r\n    Write-Host ''\r\n    if ($created) { Write-Host 'Certificate created in LocalMachine\\My (private key cannot be exported).' -ForegroundColor Green }\r\n    else { Write-Host 'A valid certificate from an earlier run is reused.' -ForegroundColor Green }\r\n    Write-Host ('  Thumbprint: ' + $cert.Thumbprint)\r\n    Write-Host ('  Valid until: ' + $cert.NotAfter.ToString('yyyy-MM-dd'))\r\n    Write-Host ('  Public part: ' + $cerPath)\r\n    Write-Host ''\r\n    Write-Host 'Next: give the .cer file (public part only, no secret) to the tenant administrator for Register-EP365AtlasAccessCollectApp.ps1.'\r\n    return $cert\r\n}\r\n\r\nfunction Install-EP365AccessCollector {\r\n    param(\r\n        [string]$TenantId, [string]$ClientId, [string]$DriveId, [string]$InboxItemId, [string]$TaskAccount, [string]$CertificateThumbprint,\r\n        [string]$DailyAt = '04:30', [string]$Proxy, [switch]$StartNow, [switch]$NoTasks, [string]$Root\r\n    )\r\n    Assert-RunAsAdministrator\r\n    $preset = Get-AccessPreset\r\n    if ($TenantId -notmatch $script:EP365GuidRx) { throw ('-TenantId must be the tenant GUID: ' + $TenantId) }\r\n    if ($TenantId.ToLowerInvariant() -ne ([string](Get-Prop $preset 'tenantId')).ToLowerInvariant()) { throw ('This script was downloaded from Atlas for tenant ' + (Get-Prop $preset 'tenantId') + ', not ' + $TenantId + '.') }\r\n    if ($ClientId -notmatch $script:EP365GuidRx) { throw ('-ClientId must be the application (client) GUID: ' + $ClientId) }\r\n    if (-not $NoTasks -and (-not $DriveId -or -not $InboxItemId)) { throw '-DriveId and -InboxItemId are required for the scheduled upload (Register-EP365AtlasAccessCollectApp.ps1 prints them).' }\r\n    if ($DriveId -and $DriveId -notmatch '^b![A-Za-z0-9_-]+$') { throw ('-DriveId must be the Graph drive id of the library EP365AtlasAccessCollect (starts with b!): ' + $DriveId) }\r\n    if ($InboxItemId -and $InboxItemId -notmatch '^[A-Za-z0-9!_-]{8,}$') { throw ('-InboxItemId must be the Graph item id of the Inbox folder: ' + $InboxItemId) }\r\n    if (-not (Test-TimeOfDay $DailyAt)) { throw ('-DailyAt must be HH:mm: ' + $DailyAt) }\r\n    if ($Proxy -and $Proxy -notmatch '^https?://[^\\s]+$') { throw ('-Proxy must be an http(s) URL: ' + $Proxy) }\r\n    $TaskAccount = Resolve-InstallAccount -TaskAccount $TaskAccount -NoTasks:$NoTasks\r\n    if ($TaskAccount -notmatch '^[^\\\\/\\s]+\\\\[^\\\\/]+$') { throw ('The account must be DOMAIN\\name (a gMSA ends with $): ' + $TaskAccount) }\r\n    $paths = Get-CollectorPaths $Root\r\n    if (-not $CertificateThumbprint) {\r\n        $info = $null\r\n        try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n        $CertificateThumbprint = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n        if (-not $CertificateThumbprint) { throw 'No certificate yet: run -NewCertificate first (or pass -CertificateThumbprint).' }\r\n    }\r\n    if ($CertificateThumbprint -notmatch '^[0-9A-Fa-f]{40}$') { throw ('The certificate thumbprint is invalid: ' + $CertificateThumbprint) }\r\n    $cert = Find-CollectorCertificate $CertificateThumbprint\r\n    if ($null -eq $cert -or -not $cert.HasPrivateKey) { throw ('Certificate ' + $CertificateThumbprint + ' with its private key is not in LocalMachine\\My on this computer.') }\r\n    $cfg = [ordered]@{\r\n        version               = 1\r\n        tenantId              = $TenantId.ToLowerInvariant()\r\n        tenantUrl             = [string](Get-Prop $preset 'tenantUrl')\r\n        clientId              = $ClientId.ToLowerInvariant()\r\n        driveId               = (ConvertTo-NullableString $DriveId)\r\n        inboxItemId           = (ConvertTo-NullableString $InboxItemId)\r\n        certificateThumbprint = $CertificateThumbprint.ToUpperInvariant()\r\n        taskAccount           = $TaskAccount\r\n        tasks                 = (-not $NoTasks)\r\n        proxy                 = (ConvertTo-NullableString $Proxy)\r\n        schedule              = [ordered]@{ dailyAt = $DailyAt }\r\n        installedAt           = (Get-UtcNowIso)\r\n        collectorVersion      = $script:EP365AccessCollectorVersion\r\n    }\r\n    $credential = $null\r\n    if (-not $NoTasks -and -not $TaskAccount.EndsWith('$')) {\r\n        $credential = Get-Credential -UserName $TaskAccount -Message 'Password of the account that runs the EP365 Atlas access task. Windows Task Scheduler stores it; the collector does not.'\r\n        if ($null -eq $credential) { throw 'No password entered; nothing was installed.' }\r\n    }\r\n    Write-Host 'Installing the EP365 Atlas access collector' -ForegroundColor Cyan\r\n    Initialize-CollectorFolder -Paths $paths -TaskAccount $TaskAccount\r\n    Write-Host ('  Folder ' + $paths.Root + ' (SYSTEM, Administrators, ' + $TaskAccount + ')')\r\n    if ($script:EP365ScriptPath -and $script:EP365ScriptPath -ine $paths.Script) { [System.IO.File]::Copy($script:EP365ScriptPath, $paths.Script, $true) }\r\n    Write-Host ('  Script ' + $paths.Script + ' (' + @(Get-AccessPlaces $preset).Count + ' place(s) from Atlas)')\r\n    Write-JsonFile -Path $paths.Config -Object $cfg\r\n    Write-Host ('  Configuration ' + $paths.Config)\r\n    Grant-CertificateKeyRead -Certificate $cert -Account $TaskAccount\r\n    Write-Host ('  ' + $TaskAccount + ' may use the private key of certificate ' + $cert.Thumbprint)\r\n    if (-not $NoTasks) {\r\n        $spec = [pscustomobject]@{ Name = $script:EP365AccessTask; Arguments = ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"' + $paths.Script + '\" -Upload'); Kind = 'Daily'; At = $DailyAt; Day = $null; EveryMinutes = $null; LimitMinutes = 360 }\r\n        Register-CollectorTasks -Specs @($spec) -TaskAccount $TaskAccount -Credential $credential -WorkingDirectory $paths.Root\r\n    }\r\n    Write-Host ''\r\n    Write-Host 'Connection test:'\r\n    $bad = Invoke-EP365AccessTestConnection -Root $Root\r\n    if ($bad -gt 0) { Write-Host 'Some checks failed. Admin consent can take a few minutes to apply; run -TestConnection again later.' -ForegroundColor Yellow }\r\n    if ($StartNow -and -not $NoTasks) {\r\n        Start-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365AccessTask\r\n        Write-Host '  The first collection is running now.'\r\n    }\r\n    Write-Host ''\r\n    if ($NoTasks) { Write-Host ('Run .\\Invoke-EP365AtlasAccessCollector.ps1 -OutputPath <folder> and import the ZIP in Atlas (Access > Snapshots and differences).') }\r\n    else { Write-Host ('Daily collection at ' + $DailyAt + '. Snapshots wait in the Inbox of the library EP365AtlasAccessCollect until an Atlas administrator opens Access > Snapshots and differences.') }\r\n    Write-Host 'To change the places: download the script from Atlas again and run -Install again.'\r\n}\r\n\r\nfunction Uninstall-EP365AccessCollector {\r\n    param([string]$Root, [switch]$KeepCertificate)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    $t = Get-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365AccessTask -ErrorAction SilentlyContinue\r\n    if ($null -ne $t) { Unregister-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365AccessTask -Confirm:$false; Write-Host ('  Task ' + $script:EP365AccessTask + ' removed') }\r\n    $cfg = $null; $info = $null\r\n    try { $cfg = Read-JsonFile $paths.Config } catch { }\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { }\r\n    $thumb = ConvertTo-NullableString (Get-Prop $cfg 'certificateThumbprint')\r\n    if (-not $thumb) { $thumb = ConvertTo-NullableString (Get-Prop $info 'thumbprint') }\r\n    $queued = @(Get-QueueFiles $paths.Queue).Count\r\n    if ($queued -gt 0) { Write-Host ('  {0} snapshot(s) in the queue were never uploaded and are deleted with the folder.' -f $queued) -ForegroundColor Yellow }\r\n    if ($thumb -and -not $KeepCertificate) {\r\n        $cert = Find-CollectorCertificate $thumb\r\n        if ($null -ne $cert) {\r\n            $keyFile = Get-CertificateKeyFile $cert\r\n            $store = New-Object System.Security.Cryptography.X509Certificates.X509Store ('My', 'LocalMachine')\r\n            $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite)\r\n            try { $store.Remove($cert) } finally { $store.Close() }\r\n            if ($keyFile -and (Test-Path -LiteralPath $keyFile)) { [System.IO.File]::Delete($keyFile) }\r\n            Write-Host ('  Certificate ' + $thumb + ' and its key removed')\r\n        }\r\n    }\r\n    if ((Test-Path -LiteralPath $paths.Root) -and ($paths.Root.TrimEnd('\\') -like '*\\EP365AtlasAccess')) {\r\n        [System.IO.Directory]::Delete($paths.Root, $true)\r\n        Write-Host ('  Folder ' + $paths.Root + ' removed')\r\n    }\r\n    $client = ConvertTo-NullableString (Get-Prop $cfg 'clientId')\r\n    Write-Host ''\r\n    Write-Host 'The access collector is removed from this computer.' -ForegroundColor Green\r\n    if ($client) { Write-Host ('Ask the tenant administrator to delete the Entra application ' + $client + ' (App registrations); that ends its access to SharePoint and Microsoft Graph.') }\r\n}\r\n\r\n# ===================== access 90: entry point (skipped when the tests dot-source this script) =====================\r\nif ($env:EP365_COLLECTOR_TEST -ne '1') {\r\n    try {\r\n        switch ($PSCmdlet.ParameterSetName) {\r\n            'NewCertificate' { $null = New-EP365AccessCertificate }\r\n            'Install' {\r\n                Install-EP365AccessCollector -TenantId $TenantId -ClientId $ClientId -DriveId $DriveId -InboxItemId $InboxItemId -TaskAccount $TaskAccount `\r\n                    -CertificateThumbprint $CertificateThumbprint -DailyAt $DailyAt -Proxy $Proxy -StartNow:$StartNow -NoTasks:$NoTasks\r\n            }\r\n            'Upload' {\r\n                $script:EP365Quiet = $true\r\n                $sent = Invoke-EP365AccessUploadRun -Modules $Modules -ModuleTimeoutMinutes $ModuleTimeoutMinutes\r\n                if ($sent.Error) { exit 1 }\r\n            }\r\n            'TestConnection' {\r\n                $bad = Invoke-EP365AccessTestConnection\r\n                if ($bad -gt 0) { exit 1 }\r\n            }\r\n            'Uninstall' { Uninstall-EP365AccessCollector -KeepCertificate:$KeepCertificate }\r\n            default { $null = Invoke-EP365AccessExport -OutputPath $OutputPath -Modules $Modules -ModuleTimeoutMinutes $ModuleTimeoutMinutes }\r\n        }\r\n        exit 0\r\n    } catch {\r\n        $msg = Format-ErrorText $_\r\n        if ($script:EP365TaskLogPath) { Write-CollectorLog -Level ERROR -Message ('EP365 Atlas access collector failed: ' + $msg) }\r\n        Write-Host ('EP365 Atlas access collector failed: ' + $msg) -ForegroundColor Red\r\n        exit 1\r\n    }\r\n}\r\n",o="Register-EP365AtlasAccessCollectApp.ps1",s="<#\r\n.SYNOPSIS\r\nEP365 Atlas - registers the Entra application of the access collector (step 2).\r\n\r\n.DESCRIPTION\r\nRun ONCE by a tenant administrator (Global Administrator, or Privileged Role Administrator\r\ntogether with an Application Administrator), on any computer with the Microsoft Graph PowerShell\r\nmodule Microsoft.Graph.Authentication (Windows PowerShell 5.1 or PowerShell 7).\r\n\r\nWhat it does, all through Microsoft Graph, signed in as you (delegated):\r\n  1. reads the Atlas site and its library EP365AtlasAccessCollect (ids for the collector),\r\n  2. creates the application \"EP365 Atlas access collector\" in Entra ID with the PUBLIC part of\r\n     the certificate that -NewCertificate created (no secret, no password),\r\n  3. adds these application permissions and grants the admin consent:\r\n       SharePoint       Sites.FullControl.All  - reading role assignments of sites, lists and items\r\n                                                 needs full control in SharePoint (app-only)\r\n       Microsoft Graph  Sites.FullControl.All  - reading the Sites.Selected grants of applications\r\n                                                 (/sites/{id}/permissions) and uploading the\r\n                                                 snapshot into the Inbox folder of the library\r\n       Microsoft Graph  GroupMember.Read.All   - people in Entra ID groups\r\n     The collector itself only reads, but these permissions would allow changes: keep the\r\n     certificate on a protected server and remove the application when it is not used.\r\n  4. creates the folders Inbox and Inbox/<tenant id> in the library when they are missing,\r\n  5. prints the values and the exact -Install command.\r\n\r\nSign-in scopes: Application.ReadWrite.All, AppRoleAssignment.ReadWrite.All, Sites.ReadWrite.All.\r\n\r\nRun it again with -ClientId of an existing collector application to switch it to a renewed\r\ncertificate and to repeat the consent (nothing is created twice).\r\n\r\n.PARAMETER SiteUrl\r\nURL of the SharePoint site where Atlas runs, for example https://contoso.sharepoint.com/sites/atlas.\r\n\r\n.PARAMETER ListId\r\nGUID of the library EP365AtlasAccessCollect (Atlas shows it in Access > Snapshots and\r\ndifferences > Scheduled collection). Without it the library is looked up by its name.\r\n\r\n.PARAMETER CertificatePath\r\nThe .cer file from the collector computer (ep365-atlas-access-collector.cer).\r\n\r\n.PARAMETER ClientId\r\nApplication (client) id of an existing access collector application to update instead of creating one.\r\n\r\n.PARAMETER TenantId\r\nTenant to sign in to (default: the tenant of your account).\r\n\r\n.EXAMPLE\r\n.\\Register-EP365AtlasAccessCollectApp.ps1 -SiteUrl https://contoso.sharepoint.com/sites/atlas -ListId 00000000-0000-0000-0000-000000000000 -CertificatePath .\\ep365-atlas-access-collector.cer\r\n\r\n.NOTES\r\nEP365 Atlas access collector - registration script.\r\n#>\r\n#Requires -Version 5.1\r\n[CmdletBinding()]\r\nparam(\r\n    [Parameter(Mandatory = $true)][string]$SiteUrl,\r\n    [Parameter(Mandatory = $true)][string]$CertificatePath,\r\n    [string]$ListId,\r\n    [string]$ClientId,\r\n    [string]$TenantId,\r\n    [string]$LibraryName = 'EP365AtlasAccessCollect'\r\n)\r\n\r\n$ErrorActionPreference = 'Stop'\r\nSet-StrictMode -Off\r\n$GraphAppId = '00000003-0000-0000-c000-000000000000'\r\n$SharePointAppId = '00000003-0000-0ff1-ce00-000000000000'\r\n$GuidRx = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\r\n$Wanted = @(\r\n    @{ Resource = $SharePointAppId; Value = 'Sites.FullControl.All'; Label = 'SharePoint' },\r\n    @{ Resource = $GraphAppId; Value = 'Sites.FullControl.All'; Label = 'Microsoft Graph' },\r\n    @{ Resource = $GraphAppId; Value = 'GroupMember.Read.All'; Label = 'Microsoft Graph' }\r\n)\r\n\r\nfunction Write-Step { param([string]$Text) Write-Host ('- ' + $Text) }\r\n\r\nfunction Invoke-Graph {\r\n    param([string]$Method, [string]$Path, $Body)\r\n    $uri = 'https://graph.microsoft.com/v1.0' + $Path\r\n    if ($null -ne $Body) {\r\n        return (Invoke-MgGraphRequest -Method $Method -Uri $uri -Body (ConvertTo-Json -InputObject $Body -Depth 10 -Compress) -ContentType 'application/json' -OutputType PSObject)\r\n    }\r\n    return (Invoke-MgGraphRequest -Method $Method -Uri $uri -OutputType PSObject)\r\n}\r\n\r\nfunction Invoke-GraphRetry {\r\n    # New applications and service principals take a moment to replicate: retry 404/400 a few times.\r\n    param([string]$Method, [string]$Path, $Body, [int]$Attempts = 6)\r\n    for ($i = 1; ; $i++) {\r\n        try { return (Invoke-Graph -Method $Method -Path $Path -Body $Body) }\r\n        catch {\r\n            $text = [string]$_\r\n            if ($i -ge $Attempts -or $text -notmatch '(404|NotFound|does not exist|Request_ResourceNotFound|400|BadRequest)') { throw }\r\n            Start-Sleep -Seconds (5 * $i)\r\n        }\r\n    }\r\n}\r\n\r\nfunction Get-ChildFolder {\r\n    # Folder <Name> under the drive item <ParentPath> ('' = root); created when missing.\r\n    param([string]$DriveId, [string]$ParentPath, [string]$Name)\r\n    $path = $Name\r\n    if ($ParentPath) { $path = $ParentPath + '/' + $Name }\r\n    try {\r\n        $f = Invoke-Graph -Method GET -Path ('/drives/' + $DriveId + '/root:/' + $path + '?$select=id,name,folder')\r\n        if ($null -eq $f.folder) { throw ($path + ' in the library is a file, not a folder. Rename or delete it and run the script again.') }\r\n        return $f\r\n    } catch {\r\n        if ([string]$_ -notmatch '(404|NotFound|itemNotFound)') { throw }\r\n    }\r\n    $parent = '/drives/' + $DriveId + '/root'\r\n    if ($ParentPath) { $parent += ':/' + $ParentPath + ':' }\r\n    return (Invoke-Graph -Method POST -Path ($parent + '/children') -Body ([ordered]@{ name = $Name; folder = @{}; '@microsoft.graph.conflictBehavior' = 'fail' }))\r\n}\r\n\r\n# ---------- checks before anything changes ----------\r\nif (-not (Get-Module -ListAvailable -Name Microsoft.Graph.Authentication)) {\r\n    throw 'The module Microsoft.Graph.Authentication is missing. Install it first: Install-Module Microsoft.Graph.Authentication -Scope CurrentUser'\r\n}\r\nif ($SiteUrl -notmatch '^https://([A-Za-z0-9-]+\\.sharepoint\\.com)(/.*)?$') { throw ('-SiteUrl must be https://<tenant>.sharepoint.com/sites/<atlas>: ' + $SiteUrl) }\r\n$siteHost = $Matches[1]\r\n$sitePath = ($Matches[2] -replace '/+$', '')\r\nif ($ListId -and $ListId -notmatch $GuidRx) { throw ('-ListId must be a GUID: ' + $ListId) }\r\nif ($ClientId -and $ClientId -notmatch $GuidRx) { throw ('-ClientId must be a GUID: ' + $ClientId) }\r\n$cerFull = (Resolve-Path -LiteralPath $CertificatePath).ProviderPath\r\n$cer = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (, [System.IO.File]::ReadAllBytes($cerFull))\r\nif ($cer.HasPrivateKey) { throw 'The certificate file contains a private key. Use the .cer file (public part only) that -NewCertificate wrote.' }\r\nif ($cer.NotAfter -lt (Get-Date)) { throw ('The certificate expired on ' + $cer.NotAfter.ToString('yyyy-MM-dd') + '. Create a new one with -NewCertificate.') }\r\n\r\nWrite-Host 'EP365 Atlas - registration of the access collector application' -ForegroundColor Cyan\r\n$connect = @{ Scopes = @('Application.ReadWrite.All', 'AppRoleAssignment.ReadWrite.All', 'Sites.ReadWrite.All'); NoWelcome = $true }\r\nif ($TenantId) { $connect.TenantId = $TenantId }\r\nConnect-MgGraph @connect\r\n$ctx = Get-MgContext\r\n$tenant = ([string]$ctx.TenantId).ToLowerInvariant()\r\nWrite-Step ('Signed in as ' + $ctx.Account + ', tenant ' + $tenant)\r\n\r\n# ---------- 1. site, library, drive ----------\r\n$siteRef = '/sites/' + $siteHost\r\nif ($sitePath) { $siteRef += ':' + $sitePath + ':' }\r\n$site = Invoke-Graph -Method GET -Path ($siteRef + '?$select=id,webUrl,displayName')\r\n$siteId = [string]$site.id\r\nWrite-Step ('Site ' + $site.webUrl)\r\nif (-not $ListId) {\r\n    $lists = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists?$select=id,name,displayName&$top=999')\r\n    $hit = @($lists.value | Where-Object { $_.name -eq $LibraryName -or $_.displayName -eq $LibraryName })\r\n    if ($hit.Count -ne 1) { throw ('The library ' + $LibraryName + ' was not found by name. Copy the command with -ListId from Atlas (Access > Snapshots and differences > Scheduled collection).') }\r\n    $ListId = [string]$hit[0].id\r\n}\r\n$list = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists/' + $ListId + '?$select=id,name,displayName')\r\nif ($list.name -ne $LibraryName) { throw ('The list ' + $ListId + ' is ' + $list.name + ', not the Atlas library ' + $LibraryName + '.') }\r\n$drive = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists/' + $ListId + '/drive?$select=id')\r\n$driveId = [string]$drive.id\r\nWrite-Step ('Library ' + $list.name + ' (drive ' + $driveId + ')')\r\n\r\n# ---------- 2. app roles of SharePoint and Microsoft Graph ----------\r\n$resources = @{}\r\nforeach ($w in $Wanted) {\r\n    if (-not $resources.ContainsKey($w.Resource)) {\r\n        $r = Invoke-Graph -Method GET -Path (\"/servicePrincipals?`$filter=appId eq '\" + $w.Resource + \"'&`$select=id,appRoles\")\r\n        $resources[$w.Resource] = @($r.value)[0]\r\n        if ($null -eq $resources[$w.Resource]) { throw ('The service principal of ' + $w.Label + ' is missing in this tenant.') }\r\n    }\r\n    $role = @($resources[$w.Resource].appRoles | Where-Object { $_.value -eq $w.Value -and @($_.allowedMemberTypes) -contains 'Application' })[0]\r\n    if ($null -eq $role) { throw ('The application permission ' + $w.Value + ' is not offered by ' + $w.Label + ' in this tenant.') }\r\n    $w.RoleId = [string]$role.id\r\n    Write-Step ($w.Label + ' ' + $w.Value + ' = app role ' + $w.RoleId)\r\n}\r\n\r\n# ---------- 3. application with the certificate ----------\r\n$key = [ordered]@{ type = 'AsymmetricX509Cert'; usage = 'Verify'; key = [Convert]::ToBase64String($cer.RawData); displayName = $cer.Subject }\r\n$required = @()\r\nforeach ($res in @($SharePointAppId, $GraphAppId)) {\r\n    $access = @($Wanted | Where-Object { $_.Resource -eq $res } | ForEach-Object { [ordered]@{ id = $_.RoleId; type = 'Role' } })\r\n    $required += [ordered]@{ resourceAppId = $res; resourceAccess = $access }\r\n}\r\nif ($ClientId) {\r\n    $app = @((Invoke-Graph -Method GET -Path (\"/applications?`$filter=appId eq '\" + $ClientId + \"'&`$select=id,appId,displayName\")).value)[0]\r\n    if ($null -eq $app) { throw ('No application with client id ' + $ClientId + ' in this tenant.') }\r\n    # keyCredentials PATCH replaces the whole list (Graph never returns existing key data): run -Install next.\r\n    Invoke-Graph -Method PATCH -Path ('/applications/' + $app.id) -Body ([ordered]@{ keyCredentials = @($key); requiredResourceAccess = $required }) | Out-Null\r\n    Write-Step ('Application ' + $app.displayName + ' now signs in with the certificate ' + $cer.Thumbprint + ' only - run -Install next')\r\n} else {\r\n    $body = [ordered]@{\r\n        displayName            = 'EP365 Atlas access collector'\r\n        signInAudience         = 'AzureADMyOrg'\r\n        notes                  = 'EP365 Atlas access collector: reads permissions of SharePoint places and Sites.Selected grants, uploads snapshots into the Inbox of the library ' + $LibraryName + ' on ' + $site.webUrl + '.'\r\n        keyCredentials         = @($key)\r\n        requiredResourceAccess = $required\r\n    }\r\n    $app = Invoke-Graph -Method POST -Path '/applications' -Body $body\r\n    Write-Step ('Application ' + $app.displayName + ' created (client id ' + $app.appId + ')')\r\n}\r\n$ClientId = [string]$app.appId\r\n$spList = Invoke-GraphRetry -Method GET -Path (\"/servicePrincipals?`$filter=appId eq '\" + $ClientId + \"'&`$select=id\")\r\n$sp = @($spList.value)[0]\r\nif ($null -eq $sp) { $sp = Invoke-GraphRetry -Method POST -Path '/servicePrincipals' -Body @{ appId = $ClientId } }\r\nWrite-Step ('Service principal ' + $sp.id)\r\n\r\n# ---------- 4. admin consent ----------\r\n$assigned = Invoke-Graph -Method GET -Path ('/servicePrincipals/' + $sp.id + '/appRoleAssignments')\r\nforeach ($w in $Wanted) {\r\n    $resId = [string]$resources[$w.Resource].id\r\n    if (@($assigned.value | Where-Object { $_.appRoleId -eq $w.RoleId -and $_.resourceId -eq $resId }).Count -eq 0) {\r\n        Invoke-GraphRetry -Method POST -Path ('/servicePrincipals/' + $sp.id + '/appRoleAssignments') -Body ([ordered]@{ principalId = $sp.id; resourceId = $resId; appRoleId = $w.RoleId }) | Out-Null\r\n        Write-Step ('Admin consent granted: ' + $w.Label + ' ' + $w.Value)\r\n    } else {\r\n        Write-Step ('Admin consent exists: ' + $w.Label + ' ' + $w.Value)\r\n    }\r\n}\r\n\r\n# ---------- 5. Inbox and Inbox/<tenant id> ----------\r\n$inbox = Get-ChildFolder -DriveId $driveId -ParentPath '' -Name 'Inbox'\r\n$inboxItemId = [string]$inbox.id\r\n[void](Get-ChildFolder -DriveId $driveId -ParentPath 'Inbox' -Name $tenant)\r\nWrite-Step ('Folders Inbox and Inbox/' + $tenant + ' ready (Inbox item ' + $inboxItemId + ')')\r\n\r\nWrite-Host ''\r\nWrite-Host 'Done. Values for the collector (no secret among them):' -ForegroundColor Green\r\nWrite-Host ('  TenantId     ' + $tenant)\r\nWrite-Host ('  ClientId     ' + $ClientId)\r\nWrite-Host ('  DriveId      ' + $driveId)\r\nWrite-Host ('  InboxItemId  ' + $inboxItemId)\r\nWrite-Host ''\r\nWrite-Host 'On the collector computer, in an elevated Windows PowerShell 5.1, run (replace the task account):' -ForegroundColor Cyan\r\nWrite-Host ('.\\Invoke-EP365AtlasAccessCollector.ps1 -Install -TenantId ' + $tenant + ' -ClientId ' + $ClientId + ' -DriveId ' + $driveId + ' -InboxItemId ' + $inboxItemId + ' -TaskAccount DOMAIN\\account$')\r\nWrite-Host ''\r\nWrite-Host 'The admin consent can take a few minutes to apply. Do not delete or recreate the folder Inbox.'\r\n"}
}]);